{"command":"cat > /tmp/ptytest.py << 'PY'
import os, pty, subprocess, sys, time, select
def run(args, inp, rows=24, cols=80, env_extra=None, stdin_tty=False):
    master, slave = pty.openpty()
    # set winsize
    import fcntl, termios, struct
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    env=os.environ.copy(); env["TERM"]="xterm"; 
    if env_extra: env.update(env_extra)
    if stdin_tty:
        p=subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
        os.close(slave)
        # don't send input (tty)
    else:
        p=subprocess.Popen(args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env, close_fds=True)
        os.close(slave)
        p.stdin.write(inp); p.stdin.close()
    out=b""
    while True:
        r,_,_=select.select([master],[],[],0.5)
        if r:
            try:
                data=os.read(master, 65536)
            except OSError:
                break
            if not data: break
            out+=data
        if p.poll() is not None:
            # drain
            try:
                while True:
                    data=os.read(master,65536)
                    if not data: break
                    out+=data
            except: pass
            break
    rc=p.wait()
    os.close(master)
    return out, rc

xml=b"<root><a>hello</a></root>"
for args in [["./executable"],["./executable","--no-color"],["./executable","-c"],["./executable","--no-color","--color"]]:
