package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

const versionText = "xq version 1.4.0\n"
const helpText = "Command-line XML and HTML beautifier and content extractor\n\nUsage:\n  xq [flags]\n\nFlags:\n  -a, --attr string      Extract an attribute value instead of node content for provided CSS query\n  -c, --color            Force colorful output\n      --compact          Compact JSON output (no indentation)\n  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)\n  -e, --extract string   Extract a single node from XML\n  -h, --help             Print this help message\n  -m, --html             Use HTML formatter\n  -i, --in-place         Format file in place\n      --indent int       Use the given number of spaces for indentation (default 2)\n  -j, --json             Output the result as JSON\n      --no-color         Disable colorful output\n  -n, --node             Return the node content instead of text\n  -q, --query string     Extract the node(s) using CSS selector\n      --tab              Use tabs for indentation\n  -v, --version          Print version information\n  -x, --xpath string     Extract the node(s) from XML\n"

type options struct {
	attr     string
	color    bool
	compact  bool
	depth    int
	extract  string
	help     bool
	html     bool
	inPlace  bool
	indent   int
	json     bool
	noColor  bool
	node     bool
	query    string
	tab      bool
	version  bool
	xpath    string
	indentUnit string
}

type flagSpec struct {
	long  string
	short rune
	kind  string // "bool", "string", "int"
	set   func(o *options, v string) error
}

func flagDisplay(s *flagSpec) string {
	if s.short != 0 {
		return fmt.Sprintf("-%c, --%s", s.short, s.long)
	}
	return "--" + s.long
}

func parseBoolValue(s string) (bool, error) {
	b, err := strconv.ParseBool(s)
	if err != nil {
		return false, err
	}
	return b, nil
}

func makeSpecs(o *options) ([]*flagSpec, map[string]*flagSpec, map[rune]*flagSpec) {
	var specs []*flagSpec
	add := func(long string, short rune, kind string, set func(o *options, v string) error) {
		specs = append(specs, &flagSpec{long: long, short: short, kind: kind, set: set})
	}
	boolSet := func(dst *bool) func(*options, string) error {
		return func(oo *options, v string) error {
			b, err := parseBoolValue(v)
			if err != nil {
				return err
			}
			*dst = b
			return nil
		}
	}
	strSet := func(dst *string) func(*options, string) error {
		return func(oo *options, v string) error { *dst = v; return nil }
	}
	_ = strSet
	add("attr", 'a', "string", func(oo *options, v string) error { oo.attr = v; return nil })
	add("color", 'c', "bool", boolSet(&o.color))
	add("compact", 0, "bool", boolSet(&o.compact))
	add("depth", 'd', "int", func(oo *options, v string) error {
		n, err := strconv.ParseInt(v, 0, 64)
		if err != nil { return err }
		oo.depth = int(n); return nil
	})
	add("extract", 'e', "string", func(oo *options, v string) error { oo.extract = v; return nil })
	add("help", 'h', "bool", boolSet(&o.help))
	add("html", 'm', "bool", boolSet(&o.html))
	add("in-place", 'i', "bool", boolSet(&o.inPlace))
	add("indent", 0, "int", func(oo *options, v string) error {
		n, err := strconv.ParseInt(v, 0, 64)
		if err != nil { return err }
		oo.indent = int(n); return nil
	})
	add("json", 'j', "bool", boolSet(&o.json))
	add("no-color", 0, "bool", boolSet(&o.noColor))
	add("node", 'n', "bool", boolSet(&o.node))
	add("query", 'q', "string", func(oo *options, v string) error { oo.query = v; return nil })
	add("tab", 0, "bool", boolSet(&o.tab))
	add("version", 'v', "bool", boolSet(&o.version))
	add("xpath", 'x', "string", func(oo *options, v string) error { oo.xpath = v; return nil })
	byLong := map[string]*flagSpec{}
	byShort := map[rune]*flagSpec{}
	for _, s := range specs {
		byLong[s.long] = s
		if s.short != 0 { byShort[s.short] = s }
	}
	return specs, byLong, byShort
}

func setFlagValue(spec *flagSpec, o *options, raw string) error {
	// pflag error wording for bad bool/int values
	if spec.kind == "bool" {
		if _, err := strconv.ParseBool(raw); err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", raw, flagDisplay(spec), err)
		}
	}
	if spec.kind == "int" {
		if _, err := strconv.ParseInt(raw, 0, 64); err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", raw, flagDisplay(spec), err)
		}
	}
	return spec.set(o, raw)
}

func parseFlags(argv []string) (*options, []string, error) {
	o := &options{indent: 2, depth: -1}
	_, byLong, byShort := makeSpecs(o)
	var positional []string
	endFlags := false
	i := 0
	for i < len(argv) {
		arg := argv[i]
		i++
		if endFlags || arg == "" || arg[0] != '-' || arg == "-" {
			positional = append(positional, arg)
			continue
		}
		if arg == "--" {
			endFlags = true
			continue
		}
		if strings.HasPrefix(arg, "--") {
			body := arg[2:]
			name := body
			val := ""
			hasVal := false
			if eq := strings.Index(body, "="); eq >= 0 {
				name = body[:eq]
				val = body[eq+1:]
				hasVal = true
			}
			spec, ok := byLong[name]
			if !ok {
				return nil, nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if spec.kind == "bool" {
				if !hasVal { val = "true" }
				if err := setFlagValue(spec, o, val); err != nil { return nil, nil, err }
			} else {
				if !hasVal {
					if i >= len(argv) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					val = argv[i]; i++
				}
				if err := setFlagValue(spec, o, val); err != nil { return nil, nil, err }
			}
			continue
		}
		// shorthand cluster
		runes := []rune(arg[1:])
		consumed := false
		for idx, ch := range runes {
			spec, ok := byShort[ch]
			if !ok {
				return nil, nil, fmt.Errorf("unknown shorthand flag: %q in -%s", ch, string(runes[idx:]))
			}
			if spec.kind == "bool" {
				rest := runes[idx+1:]
				if len(rest) > 0 && rest[0] == '=' {
					val := string(rest[1:])
					if err := setFlagValue(spec, o, val); err != nil { return nil, nil, err }
					consumed = true
					break
				}
				if err := setFlagValue(spec, o, "true"); err != nil { return nil, nil, err }
				continue
			}
			// value flag
			rest := runes[idx+1:]
			var val string
			if len(rest) > 0 {
				if rest[0] == '=' {
					val = string(rest[1:])
				} else {
					val = string(rest)
				}
			} else {
				if i >= len(argv) {
					return nil, nil, fmt.Errorf("flag needs an argument: %q in -%s", ch, string(runes[idx:]))
				}
				val = argv[i]; i++
			}
			if err := setFlagValue(spec, o, val); err != nil { return nil, nil, err }
			consumed = true
			break
		}
		_ = consumed
	}
	return o, positional, nil
}

func isTerminal(fd uintptr) bool {
	// TCGETS ioctl on Linux
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

var currentOptions *options
var currentPalette palette

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(argv []string) int {
	opts, args, err := parseFlags(argv)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		return 1
	}
	if opts.help {
		fmt.Fprint(os.Stdout, helpText)
		return 0
	}
	if opts.version {
		fmt.Fprint(os.Stdout, versionText)
		return 0
	}
	if opts.indent < 0 || opts.indent > 8 {
		fmt.Fprint(os.Stderr, "Error: indent should be between 0-8 spaces\n")
		return 1
	}
	// prepare indent unit
	opts.indentUnit = strings.Repeat(" ", opts.indent)
	if opts.tab {
		opts.indentUnit = "\t"
	}
	currentOptions = opts

	// collect input contents
	var contents [][]byte
	if len(args) > 0 {
		for _, path := range args {
			f, err := os.Open(path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
				return 1
			}
			info, statErr := f.Stat()
			if statErr == nil && info.IsDir() {
				f.Close()
				contents = append(contents, []byte{})
				continue
			}
			data, readErr := io.ReadAll(f)
			f.Close()
			if readErr != nil {
				// treat unreadable (e.g. directory racing) as empty like original
				contents = append(contents, []byte{})
				continue
			}
			contents = append(contents, data)
		}
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprint(os.Stdout, helpText)
			return 0
		}
		data, _ := io.ReadAll(os.Stdin)
		contents = append(contents, data)
	}

	if opts.inPlace && len(args) != 1 {
		fmt.Fprint(os.Stderr, "Error: in-place formatting requires a file path (and only one file path)\n")
		return 1
	}
	if opts.attr != "" && opts.query == "" {
		fmt.Fprint(os.Stderr, "Error: query option (-q) is missed for attribute selection\n")
		return 1
	}

	// colour decision
	useColor := false
	if os.Getenv("NO_COLOR") == "" && !opts.inPlace {
		if opts.color {
			useColor = true
		} else if opts.noColor {
			useColor = false
		} else if isTerminal(os.Stdout.Fd()) && os.Getenv("TERM") != "dumb" {
			useColor = true
		}
	}
	currentPalette = palette{enabled: useColor}

	var out io.Writer = os.Stdout
	var buf *bytes.Buffer
	if opts.inPlace {
		buf = &bytes.Buffer{}
		out = buf
	}

	var lastErr error
	for _, content := range contents {
		lastErr = processContent(content, out)
	}
	if lastErr != nil {
		fmt.Fprintf(os.Stdout, "Error: %s\n", lastErr.Error())
		return 1
	}
	if opts.inPlace {
		_ = os.WriteFile(args[0], buf.Bytes(), 0644)
	}
	return 0
}

type contentKind int

const (
	kindXML contentKind = iota
	kindHTML
	kindJSON
	kindUnknown
)

func detectContent(content []byte) contentKind {
	if len(content) == 0 {
		return kindUnknown
	}
	n := 10
	if len(content) < n {
		n = len(content)
	}
	sample := strings.ToLower(string(content[:n]))
	if strings.Contains(sample, "{") || strings.Contains(sample, "[") {
		return kindJSON
	}
	if strings.Contains(sample, "html") || strings.Contains(sample, "<body") || strings.Contains(sample, "<!d") {
		return kindHTML
	}
	return kindXML
}

func processContent(content []byte, out io.Writer) error {
	opts := currentOptions
	if opts.xpath != "" {
		return processXPathQuery(content, out, false)
	}
	if opts.extract != "" {
		return processXPathQuery(content, out, true)
	}
	if opts.query != "" {
		return processCSSQuery(content, out)
	}
	if opts.json {
		return processJSONFlag(content, out)
	}
	if opts.html {
		s, err := formatHTMLString(string(content))
		fmt.Fprint(out, s)
		if err != nil {
			return err
		}
		fmt.Fprint(out, "\n")
		return nil
	}
	kind := detectContent(content)
	if kind == kindUnknown {
		return errors.New("unknown content type: 3")
	}
	var s string
	var err error
	switch kind {
