		fmt.Fprint(os.Stderr, "Error: in-place formatting requires a file path (and only one file path)\n")
		return 1
	}
	if opts.attr != "" && opts.query == "" {
		fmt.Fprint(os.Stderr, "Error: query option (-q) is missed for attribute selection\n")
		return 1
	}

	// colour decision
	useColor := false
	if os.Getenv("NO_COLOR") == "" && !opts.inPlace {
		if opts.color {
			useColor = true
		} else if opts.noColor {
			useColor = false
		} else if isTerminal(os.Stdout.Fd()) && os.Getenv("TERM") != "dumb" {
			useColor = true
		}
	}
	currentPalette = palette{enabled: useColor}

	var out io.Writer = os.Stdout
	var buf *bytes.Buffer
	if opts.inPlace {
		buf = &bytes.Buffer{}
		out = buf
	}

	var lastErr error
	for _, content := range contents {
		lastErr = processContent(content, out)
	}
	if lastErr != nil {
		fmt.Fprintf(os.Stdout, "Error: %s\n", lastErr.Error())
		return 1
	}
