		_ = os.WriteFile(args[0], buf.Bytes(), 0644)
	}
	return 0
}

type contentKind int

const (
	kindXML contentKind = iota
	kindHTML
	kindJSON
	kindUnknown
)

func detectContent(content []byte) contentKind {
	if len(content) == 0 {
		return kindUnknown
	}
	n := 10
	if len(content) < n {
		n = len(content)
	}
	sample := strings.ToLower(string(content[:n]))
	if strings.Contains(sample, "{") || strings.Contains(sample, "[") {
		return kindJSON
	}
	if strings.Contains(sample, "html") || strings.Contains(sample, "<body") || strings.Contains(sample, "<!d") {
		return kindHTML
	}
	return kindXML
}

func processContent(content []byte, out io.Writer) error {
	opts := currentOptions
	if opts.xpath != "" {
		return processXPathQuery(content, out, false)
	}
	if opts.extract != "" {
		return processXPathQuery(content, out, true)
	}
	if opts.query != "" {
		return processCSSQuery(content, out)
	}
	if opts.json {
		return processJSONFlag(content, out)
	}
	if opts.html {
		s, err := formatHTMLString(string(content))
		fmt.Fprint(out, s)
		if err != nil {
			return err
		}
		fmt.Fprint(out, "\n")
		return nil
	}
	kind := detectContent(content)
	if kind == kindUnknown {
		return errors.New("unknown content type: 3")
	}
	var s string
	var err error
	switch kind {
	case kindJSON:
		s, err = formatJSONString(string(content), opts.indentUnit)
	case kindHTML:
		s, err = formatHTMLString(string(content))
	default:
		s, err = formatXMLString(string(content))
	}
	fmt.Fprint(out, s)
	if err != nil {
		return err
	}
	fmt.Fprint(out, "\n")
	return nil
}
