// ---------- XML source ----------

type nsScope struct {
	prefixByURI map[string]string
	uriByPrefix map[string]string
	defaultURI  string
	parent      *nsScope
}

func (s *nsScope) cloneWithDecls(attrs []xml.Attr) *nsScope {
	ns := &nsScope{
		prefixByURI: map[string]string{},
		uriByPrefix: map[string]string{},
		defaultURI:  "",
	}
	if s != nil {
		for k, v := range s.prefixByURI {
			ns.prefixByURI[k] = v
		}
		for k, v := range s.uriByPrefix {
			ns.uriByPrefix[k] = v
		}
		ns.defaultURI = s.defaultURI
		ns.parent = s
	}
	for _, a := range attrs {
		if a.Name.Space == "xmlns" && a.Name.Local != "" {
			ns.uriByPrefix[a.Name.Local] = a.Value
			if _, exists := ns.prefixByURI[a.Value]; !exists {
				ns.prefixByURI[a.Value] = a.Name.Local
			} else {
				// keep first, but if overriding existing inherited mapping, replace for current uri's prefix?
				// If this declaration is for same URI, prefer this prefix if it was already declared here.
				ns.prefixByURI[a.Value] = a.Name.Local
			}
		} else if a.Name.Space == "" && a.Name.Local == "xmlns" {
			ns.defaultURI = a.Value
		}
	}
	return ns
}

func qualifiedName(space, local string, scope *nsScope, isAttr bool) string {
	if space == "" {
		return local
	}
	if space == "xmlns" {
		return "xmlns:" + local
	}
	if space == "http://www.w3.org/XML/1998/namespace" {
		return "xml:" + local
	}
	if scope != nil {
		if !isAttr && scope.defaultURI == space {
			return local
		}
		if p, ok := scope.prefixByURI[space]; ok && p != "" {
			return p + ":" + local
		}
	}
	// undeclared namespace: space is the prefix itself
	if !strings.Contains(space, "/") && !strings.Contains(space, ":") {
		return space + ":" + local
	}
	// unknown URI without declaration: use local only
	return local
}

func attrQualifiedName(a xml.Attr, scope *nsScope) string {
	if a.Name.Space == "xmlns" {
		return "xmlns:" + a.Name.Local
	}
	if a.Name.Space == "" {
		return a.Name.Local
	}
	return qualifiedName(a.Name.Space, a.Name.Local, scope, true)
}

type xmlEventSource struct {
	dec    *xml.Decoder
	scopes []*nsScope
	frames []string // qualified names stack
}

func newXMLEventSource(input string) *xmlEventSource {
	dec := xml.NewDecoder(strings.NewReader(input))
	dec.Strict = false
	return &xmlEventSource{dec: dec}
}

func (s *xmlEventSource) next() (fmtEvent, error) {
	tok, err := s.dec.Token()
	if err != nil {
		return fmtEvent{}, err
	}
	switch t := tok.(type) {
	case xml.StartElement:
		parentScope := (*nsScope)(nil)
		if len(s.scopes) > 0 {
			parentScope = s.scopes[len(s.scopes)-1]
		}
		scope := parentScope.cloneWithDecls(t.Attr)
		s.scopes = append(s.scopes, scope)
		qname := qualifiedName(t.Name.Space, t.Name.Local, scope, false)
		s.frames = append(s.frames, qname)
		attrs := make([]attrPair, 0, len(t.Attr))
		for _, a := range t.Attr {
			attrs = append(attrs, attrPair{Name: attrQualifiedName(a, scope), Value: a.Value})
		}
		return fmtEvent{kind: evStart, name: qname, attrs: attrs}, nil
	case xml.EndElement:
		qname := ""
		if len(s.frames) > 0 {
			qname = s.frames[len(s.frames)-1]
			s.frames = s.frames[:len(s.frames)-1]
			s.scopes = s.scopes[:len(s.scopes)-1]
		} else {
			qname = qualifiedName(t.Name.Space, t.Name.Local, nil, false)
		}
		return fmtEvent{kind: evEnd, name: qname}, nil
	case xml.CharData:
		return fmtEvent{kind: evText, text: string(t)}, nil
	case xml.Comment:
		return fmtEvent{kind: evComment, commentText: string(t)}, nil
	case xml.ProcInst:
		return fmtEvent{kind: evPI, piTarget: t.Target, piInst: string(t.Inst)}, nil
	case xml.Directive:
		d := string(t)
		isDT := len(d) >= 7 && strings.EqualFold(d[:7], "doctype")
		return fmtEvent{kind: evDirective, directive: d, isDoctype: isDT}, nil
	default:
		return fmtEvent{kind: evText, text: ""}, nil
	}
}

// ---------- generic format driver ----------

func formatWithSource(src eventSource, indentUnit string, isHTML bool) (string, error) {
	var sb strings.Builder
	f := &formatter{out: &sb, indentUnit: indentUnit, isHTML: isHTML, first: true}
	for {
		ev, err := src.next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return sb.String(), err
		}
		f.handle(ev)
	}
	return sb.String(), nil
}

func formatXMLString(input string) (string, error) {
	return formatWithSource(newXMLEventSource(input), currentOptions.indentUnit, false)
}

// ---------- JSON formatter ----------

type jsonFrame struct {
	isObject      bool
	count         int // completed values (for objects: key-value pairs)
	expectingKey  bool
	afterKey      bool
}

func jsonEncodeString(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(s)
	return strings.TrimRight(buf.String(), "\n")
}

func formatJSONString(input string, indentUnit string) (string, error) {
	dec := json.NewDecoder(strings.NewReader(input))
	dec.UseNumber()
	var sb strings.Builder
	var stack []*jsonFrame
	writeIndent := func(depth int) {
		if indentUnit != "" {
			sb.WriteString(strings.Repeat(indentUnit, depth))
		}
	}
	lineBreakTo := func(depth int) {
		if indentUnit != "" {
			sb.WriteString("\n")
			writeIndent(depth)
		}
	}
	completeValue := func() {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.isObject {
			if top.afterKey {
				top.afterKey = false
				top.expectingKey = true
				top.count++
			}
		} else {
			top.count++
		}
	}
	// helper to write prefix for a value token (not a key)
	valuePrefix := func(isKey bool) {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.isObject && top.afterKey && !isKey {
			sb.WriteString(": ")
			return
		}
		if top.isObject && isKey {
			// key
			if top.count > 0 {
				sb.WriteString(",")
				lineBreakTo(len(stack))
			} else {
				writeIndent(len(stack))
			}
			return
		}
		// array value
		if !top.isObject {
			if top.count > 0 {
				sb.WriteString(",")
				lineBreakTo(len(stack))
			} else {
				writeIndent(len(stack))
			}
			return
		}
	}
	_ = valuePrefix

	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return sb.String(), err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{', '[':
				// prefix
				if len(stack) > 0 {
					top := stack[len(stack)-1]
					if top.isObject && top.afterKey {
						sb.WriteString(": ")
					} else if top.isObject && top.expectingKey {
						// shouldn't happen
					} else {
						// array element
						if top.count > 0 {
							sb.WriteString(",")
							lineBreakTo(len(stack))
						} else {
							writeIndent(len(stack))
						}
					}
				}
				sb.WriteString(currentPalette.yellow(string(t)))
				isObj := t == '{'
				stack = append(stack, &jsonFrame{isObject: isObj, expectingKey: isObj})
				if indentUnit != "" {
					sb.WriteString("\n")
				}
			case '}', ']':
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				if indentUnit != "" {
					sb.WriteString("\n")
					writeIndent(len(stack))
				}
				sb.WriteString(currentPalette.yellow(string(t)))
				completeValue()
			}
		case string:
			// key or value?
			if len(stack) > 0 && stack[len(stack)-1].isObject && stack[len(stack)-1].expectingKey && !stack[len(stack)-1].afterKey {
				// key
				top := stack[len(stack)-1]
				if top.count > 0 {
					sb.WriteString(",")
					lineBreakTo(len(stack))
				} else {
					writeIndent(len(stack))
				}
				sb.WriteString(currentPalette.blue(jsonEncodeString(t)))
				top.expectingKey = false
				top.afterKey = true
			} else {
				// value
				inContainer := len(stack) > 0
				if inContainer {
					top := stack[len(stack)-1]
					if top.isObject && top.afterKey {
						sb.WriteString(": ")
					} else if !top.isObject {
						if top.count > 0 {
							sb.WriteString(",")
							lineBreakTo(len(stack))
						} else {
							writeIndent(len(stack))
						}
					}
				}
				enc := jsonEncodeString(t)
				if inContainer {
					sb.WriteString(currentPalette.green(enc))
				} else {
					sb.WriteString(enc)
				}
				completeValue()
			}
		case json.Number:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			if inContainer {
				sb.WriteString(currentPalette.green(t.String()))
			} else {
				sb.WriteString(t.String())
			}
			completeValue()
		case bool:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			s := "false"
			if t {
				s = "true"
			}
			if inContainer {
				sb.WriteString(currentPalette.green(s))
			} else {
				sb.WriteString(s)
			}
			completeValue()
		case nil:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			if inContainer {
				sb.WriteString(currentPalette.green("null"))
			} else {
				sb.WriteString("null")
			}
			completeValue()
		default:
			// float64 if UseNumber not applied somewhere
			s := fmt.Sprintf("%v", tok)
			sb.WriteString(s)
			completeValue()
		}
	}
	return sb.String(), nil
}

