package main

import (
	"bytes"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"html"
	"io"
	"strings"
)

type palette struct{ enabled bool }

func (p palette) wrap(code, s string) string {
	if !p.enabled {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0m"
}
func (p palette) yellow(s string) string { return p.wrap("33", s) }
func (p palette) green(s string) string  { return p.wrap("32", s) }
func (p palette) blue(s string) string   { return p.wrap("94", s) }

func escapeAttrValue(v string) string {
	var b strings.Builder
	for _, r := range v {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		case '\t':
			b.WriteString("&#x9;")
		case '\n':
			b.WriteString("&#xA;")
		case '\r':
			b.WriteString("&#xD;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func escapeTextXML(v string) string {
	var buf bytes.Buffer
	_ = xml.EscapeText(&buf, []byte(v))
	return buf.String()
}

// ---------- formatter events ----------

type evKind int

const (
	evStart evKind = iota
	evCompletedStart // self-closing or void
	evEnd
	evText
	evComment
	evDirective // may be doctype or other (xml)
	evPI
)

type attrPair struct {
	Name  string
	Value string
}

type fmtEvent struct {
	kind      evKind
	name      string // qualified/tag name
	attrs     []attrPair
	text      string // text content
	commentRaw string // html style full raw comment
	commentText string // xml comment inner
	directive string // raw directive inner (after <!)
	piTarget  string
	piInst    string
	isDoctype bool
	htmlComment bool // render as one blue raw fragment
}

type eventSource interface {
	next() (fmtEvent, error) // io.EOF at end
}

type fmtFrame struct {
	name         string
	pending      bool
	hasContent   bool
	childEndSeen bool
}

type formatter struct {
	out         *strings.Builder
	indentUnit  string
	isHTML      bool
	stack       []*fmtFrame
	prevKind    evKind
	hasPrev     bool
	first       bool
	afterSuffix bool // previous prolog-ish token already emitted a line break
}

func (f *formatter) lineBreak(depth int) string {
	if f.indentUnit == "" {
		return ""
	}
	return "\n" + strings.Repeat(f.indentUnit, depth)
}
func (f *formatter) flushPending() {
	if len(f.stack) > 0 && f.stack[len(f.stack)-1].pending {
		f.out.WriteString(currentPalette.yellow(">"))
		f.stack[len(f.stack)-1].pending = false
	}
}
func (f *formatter) markParentAsContent() {
	if len(f.stack) > 0 {
		top := f.stack[len(f.stack)-1]
		top.hasContent = true
		top.childEndSeen = false
	}
}

func (f *formatter) processText(raw string) string {
	s := raw
	// leading newline+indent re-indent of first content line
	if strings.TrimSpace(s) != "" {
		// find first non-space
		i := 0
		for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\r' || s[i] == '\n') {
			i++
		}
		if i > 0 && i < len(s) {
			prefix := s[:i]
			if strings.Contains(prefix, "\n") {
				lastNl := strings.LastIndex(prefix, "\n")
				after := prefix[lastNl+1:]
				if len(after) > 0 {
					depth := len(f.stack)
					s = "\n" + strings.Repeat(f.indentUnit, depth) + s[i:]
				}
			}
		}
	}
	// trim trailing spaces only
	s = strings.TrimRight(s, " ")
	if !f.isHTML && (strings.Contains(s, "&") || strings.Contains(s, "<")) {
		return "<![CDATA[" + s + "]]>"
	}
	return s
}

func (f *formatter) handle(ev fmtEvent) {
	switch ev.kind {
	case evText:
		if strings.TrimSpace(ev.text) == "" {
			return
		}
		if len(f.stack) > 0 {
			f.flushPending()
			top := f.stack[len(f.stack)-1]
			top.hasContent = true
			top.childEndSeen = false
		}
		f.out.WriteString(f.processText(ev.text))
		f.prevKind = evText
		f.hasPrev = true
		f.first = false
		f.afterSuffix = false

	case evCompletedStart:
		if len(f.stack) > 0 {
			if f.stack[len(f.stack)-1].pending && (f.prevKind == evPI || f.prevKind == evDirective) && f.afterSuffix {
				f.out.WriteString(currentPalette.yellow(">"))
				f.stack[len(f.stack)-1].pending = false
				f.out.WriteString(f.lineBreak(len(f.stack)))
			} else {
				f.flushPending()
				f.out.WriteString(f.lineBreak(len(f.stack)))
			}
			f.markParentAsContent()
		} else if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective || f.prevKind == evPI) {
			f.out.WriteString(f.lineBreak(0))
		}
		f.out.WriteString(currentPalette.yellow("<" + ev.name))
		for _, a := range ev.attrs {
			f.out.WriteString(" " + a.Name + currentPalette.green("=\""+escapeAttrValue(a.Value)+"\""))
		}
		f.out.WriteString(currentPalette.yellow("/>"))
		f.prevKind = evCompletedStart
		f.hasPrev = true
		f.first = false
		f.afterSuffix = false

	case evStart:
		if len(f.stack) > 0 {
			if f.stack[len(f.stack)-1].pending && (f.prevKind == evPI || f.prevKind == evDirective) && f.afterSuffix {
				f.out.WriteString(currentPalette.yellow(">"))
				f.stack[len(f.stack)-1].pending = false
				f.out.WriteString(f.lineBreak(len(f.stack)))
			} else {
				f.flushPending()
				f.out.WriteString(f.lineBreak(len(f.stack)))
			}
			f.markParentAsContent()
		} else if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective || f.prevKind == evPI) {
			f.out.WriteString(f.lineBreak(0))
		}
		f.out.WriteString(currentPalette.yellow("<" + ev.name))
		for _, a := range ev.attrs {
			f.out.WriteString(" " + a.Name + currentPalette.green("=\""+escapeAttrValue(a.Value)+"\""))
		}
		f.stack = append(f.stack, &fmtFrame{name: ev.name, pending: true})
		f.prevKind = evStart
		f.hasPrev = true
		f.first = false
		f.afterSuffix = false

	case evEnd:
		if len(f.stack) == 0 {
			f.out.WriteString(currentPalette.yellow("</" + ev.name + ">"))
			f.prevKind = evEnd
			f.hasPrev = true
			f.first = false
			f.afterSuffix = false
			return
		}
		frame := f.stack[len(f.stack)-1]
		if !frame.hasContent {
			if f.isHTML {
				if frame.pending {
					f.out.WriteString(currentPalette.yellow(">"))
				}
				f.out.WriteString(currentPalette.yellow("</" + ev.name + ">"))
			} else {
				f.out.WriteString(currentPalette.yellow("/>"))
			}
		} else {
			needBreak := true
			if f.afterSuffix {
				if f.prevKind == evDirective && ev.isDoctype {
					needBreak = false
				} else if f.prevKind == evPI || f.prevKind == evDirective {
					// suffix already gave a break; add the closing indentation break
					// except doctype handled above
					if f.prevKind == evDirective && !ev.isDoctype {
						needBreak = true
					}
				}
			} else if f.prevKind == evText {
				needBreak = false
			} else if f.prevKind == evComment && !frame.childEndSeen {
				needBreak = false
			} else if f.prevKind == evCompletedStart {
				needBreak = false
			}
			if needBreak {
				f.out.WriteString(f.lineBreak(len(f.stack) - 1))
			}
			if frame.pending {
				f.out.WriteString(currentPalette.yellow(">"))
			}
			f.out.WriteString(currentPalette.yellow("</" + ev.name + ">"))
		}
		// pop
		f.stack = f.stack[:len(f.stack)-1]
		if len(f.stack) > 0 {
			f.stack[len(f.stack)-1].childEndSeen = true
			f.stack[len(f.stack)-1].hasContent = true
		}
		f.prevKind = evEnd
		f.hasPrev = true
		f.first = false
		f.afterSuffix = false

	case evComment:
		if len(f.stack) > 0 {
			top := f.stack[len(f.stack)-1]
			if top.pending {
				f.out.WriteString(currentPalette.yellow(">"))
				top.pending = false
				f.out.WriteString(f.lineBreak(len(f.stack)))
			} else if f.prevKind == evText {
				// inline
			} else if f.afterSuffix {
				f.out.WriteString(f.lineBreak(len(f.stack)))
			} else {
				f.out.WriteString(f.lineBreak(len(f.stack)))
			}
		} else {
			if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective || f.prevKind == evPI) {
				f.out.WriteString(f.lineBreak(0))
			}
		}
		if ev.htmlComment {
			f.out.WriteString(currentPalette.blue(ev.commentRaw))
		} else {
			f.out.WriteString(currentPalette.blue("<!--"))
			f.out.WriteString(currentPalette.blue(ev.commentText))
			f.out.WriteString(currentPalette.blue("-->"))
		}
		if len(f.stack) == 0 && f.indentUnit != "" {
			f.out.WriteString("\n")
			f.afterSuffix = true
		} else {
			f.afterSuffix = false
		}
		f.prevKind = evComment
		f.hasPrev = true
		f.first = false

	case evPI:
		if len(f.stack) == 0 {
			if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective) {
				f.out.WriteString(f.lineBreak(0))
			}
		}
		// rendering (may panic on malformed inst like original)
		f.out.WriteString(currentPalette.yellow("<?"))
		f.out.WriteString(ev.piTarget)
		instStr := ev.piInst
		parts := strings.Split(instStr, " ")
		for _, part := range parts {
			kv := strings.SplitN(part, "=", 2)
			f.out.WriteString(" " + kv[0])
			f.out.WriteString(currentPalette.green("=" + kv[1]))
		}
		f.out.WriteString(currentPalette.yellow("?>"))
		if f.indentUnit != "" {
			f.out.WriteString("\n")
		}
		f.afterSuffix = true
		f.prevKind = evPI
		f.hasPrev = true
		f.first = false

	case evDirective:
		if ev.isDoctype {
			if len(f.stack) > 0 {
				top := f.stack[len(f.stack)-1]
				if top.pending {
					f.flushPending()
				} else if f.prevKind != evText {
					// after a child etc, place on its own line
					// only if previous wasn't start flush case; approximate
					if f.hasPrev && f.prevKind != evStart {
						f.out.WriteString(f.lineBreak(len(f.stack)))
					}
				}
				top.hasContent = true
				top.childEndSeen = false
			} else {
				if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective || f.prevKind == evPI) {
					f.out.WriteString(f.lineBreak(0))
				}
			}
			d := ev.directive
			rest := ""
			if len(d) >= 7 {
				rest = strings.TrimLeft(d[7:], " \t\r\n")
			}
			f.out.WriteString(currentPalette.yellow("<!doctype "))
			f.out.WriteString(rest)
			f.out.WriteString(currentPalette.yellow(">"))
			if f.indentUnit != "" {
				f.out.WriteString("\n")
			}
			f.afterSuffix = true
			f.prevKind = evDirective
			// remember doctype via a sentinel in prev handling: reuse isDoctype on next end is not available.
			// encode by setting a flag on frame? use package-level-ish field:
			f.lastDirectiveDoctype = true
			f.hasPrev = true
			f.first = false
		} else {
			// non-doctype directive
			if len(f.stack) == 0 {
				if !f.first && !f.afterSuffix && f.hasPrev && (f.prevKind == evComment || f.prevKind == evDirective || f.prevKind == evPI) {
					f.out.WriteString(f.lineBreak(0))
				}
			}
			f.out.WriteString(currentPalette.yellow("<!"))
			f.out.WriteString(ev.directive)
			f.out.WriteString(currentPalette.yellow(">"))
			// suffix
			if len(f.stack) > 0 {
				f.out.WriteString(f.lineBreak(len(f.stack)))
			} else if f.indentUnit != "" {
				f.out.WriteString("\n")
			}
			f.afterSuffix = true
			f.prevKind = evDirective
			f.lastDirectiveDoctype = false
			f.hasPrev = true
			f.first = false
		}
	}
}

// this field is referenced above (doctype flag)
type _unused struct{}

// We'll add field via embedding hack: actually formatter needs lastDirectiveDoctype.
// It is declared in format2.go as extension? Go doesn't allow that. We'll instead handle in handleEnd logic separately.

// ---------- XML source ----------

type nsScope struct {
	prefixByURI map[string]string
	uriByPrefix map[string]string
	defaultURI  string
	parent      *nsScope
}

func (s *nsScope) cloneWithDecls(attrs []xml.Attr) *nsScope {
	ns := &nsScope{
		prefixByURI: map[string]string{},
		uriByPrefix: map[string]string{},
		defaultURI:  "",
	}
	if s != nil {
		for k, v := range s.prefixByURI {
			ns.prefixByURI[k] = v
		}
		for k, v := range s.uriByPrefix {
			ns.uriByPrefix[k] = v
		}
		ns.defaultURI = s.defaultURI
		ns.parent = s
	}
	for _, a := range attrs {
		if a.Name.Space == "xmlns" && a.Name.Local != "" {
			ns.uriByPrefix[a.Name.Local] = a.Value
			if _, exists := ns.prefixByURI[a.Value]; !exists {
				ns.prefixByURI[a.Value] = a.Name.Local
			} else {
				// keep first, but if overriding existing inherited mapping, replace for current uri's prefix?
				// If this declaration is for same URI, prefer this prefix if it was already declared here.
				ns.prefixByURI[a.Value] = a.Name.Local
			}
		} else if a.Name.Space == "" && a.Name.Local == "xmlns" {
			ns.defaultURI = a.Value
		}
	}
	return ns
}

func qualifiedName(space, local string, scope *nsScope, isAttr bool) string {
	if space == "" {
		return local
	}
	if space == "xmlns" {
		return "xmlns:" + local
	}
	if space == "http://www.w3.org/XML/1998/namespace" {
		return "xml:" + local
	}
	if scope != nil {
		if !isAttr && scope.defaultURI == space {
			return local
		}
		if p, ok := scope.prefixByURI[space]; ok && p != "" {
			return p + ":" + local
		}
	}
	// undeclared namespace: space is the prefix itself
	if !strings.Contains(space, "/") && !strings.Contains(space, ":") {
		return space + ":" + local
	}
	// unknown URI without declaration: use local only
	return local
}

func attrQualifiedName(a xml.Attr, scope *nsScope) string {
	if a.Name.Space == "xmlns" {
		return "xmlns:" + a.Name.Local
	}
	if a.Name.Space == "" {
		return a.Name.Local
	}
	return qualifiedName(a.Name.Space, a.Name.Local, scope, true)
}

type xmlEventSource struct {
	dec    *xml.Decoder
	scopes []*nsScope
	frames []string // qualified names stack
}

func newXMLEventSource(input string) *xmlEventSource {
	dec := xml.NewDecoder(strings.NewReader(input))
	dec.Strict = false
	return &xmlEventSource{dec: dec}
}

func (s *xmlEventSource) next() (fmtEvent, error) {
	tok, err := s.dec.Token()
	if err != nil {
		return fmtEvent{}, err
	}
	switch t := tok.(type) {
	case xml.StartElement:
		parentScope := (*nsScope)(nil)
		if len(s.scopes) > 0 {
			parentScope = s.scopes[len(s.scopes)-1]
		}
		scope := parentScope.cloneWithDecls(t.Attr)
		s.scopes = append(s.scopes, scope)
		qname := qualifiedName(t.Name.Space, t.Name.Local, scope, false)
		s.frames = append(s.frames, qname)
		attrs := make([]attrPair, 0, len(t.Attr))
		for _, a := range t.Attr {
			attrs = append(attrs, attrPair{Name: attrQualifiedName(a, scope), Value: a.Value})
		}
		return fmtEvent{kind: evStart, name: qname, attrs: attrs}, nil
	case xml.EndElement:
		qname := ""
		if len(s.frames) > 0 {
			qname = s.frames[len(s.frames)-1]
			s.frames = s.frames[:len(s.frames)-1]
			s.scopes = s.scopes[:len(s.scopes)-1]
		} else {
			qname = qualifiedName(t.Name.Space, t.Name.Local, nil, false)
		}
		return fmtEvent{kind: evEnd, name: qname}, nil
	case xml.CharData:
		return fmtEvent{kind: evText, text: string(t)}, nil
	case xml.Comment:
		return fmtEvent{kind: evComment, commentText: string(t)}, nil
	case xml.ProcInst:
		return fmtEvent{kind: evPI, piTarget: t.Target, piInst: string(t.Inst)}, nil
	case xml.Directive:
		d := string(t)
		isDT := len(d) >= 7 && strings.EqualFold(d[:7], "doctype")
		return fmtEvent{kind: evDirective, directive: d, isDoctype: isDT}, nil
	default:
		return fmtEvent{kind: evText, text: ""}, nil
	}
}

// ---------- generic format driver ----------

func formatWithSource(src eventSource, indentUnit string, isHTML bool) (string, error) {
	var sb strings.Builder
	f := &formatter{out: &sb, indentUnit: indentUnit, isHTML: isHTML, first: true}
	for {
		ev, err := src.next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return sb.String(), err
		}
		f.handle(ev)
	}
	return sb.String(), nil
}

func formatXMLString(input string) (string, error) {
	return formatWithSource(newXMLEventSource(input), currentOptions.indentUnit, false)
}

// ---------- JSON formatter ----------

type jsonFrame struct {
	isObject      bool
	count         int // completed values (for objects: key-value pairs)
	expectingKey  bool
	afterKey      bool
}

func jsonEncodeString(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(s)
	return strings.TrimRight(buf.String(), "\n")
}

func formatJSONString(input string, indentUnit string) (string, error) {
	dec := json.NewDecoder(strings.NewReader(input))
	dec.UseNumber()
	var sb strings.Builder
	var stack []*jsonFrame
	writeIndent := func(depth int) {
		if indentUnit != "" {
			sb.WriteString(strings.Repeat(indentUnit, depth))
		}
	}
	lineBreakTo := func(depth int) {
		if indentUnit != "" {
			sb.WriteString("\n")
			writeIndent(depth)
		}
	}
	completeValue := func() {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.isObject {
			if top.afterKey {
				top.afterKey = false
				top.expectingKey = true
				top.count++
			}
		} else {
			top.count++
		}
	}
	// helper to write prefix for a value token (not a key)
	valuePrefix := func(isKey bool) {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.isObject && top.afterKey && !isKey {
			sb.WriteString(": ")
			return
		}
		if top.isObject && isKey {
			// key
			if top.count > 0 {
				sb.WriteString(",")
				lineBreakTo(len(stack))
			} else {
				writeIndent(len(stack))
			}
			return
		}
		// array value
		if !top.isObject {
			if top.count > 0 {
				sb.WriteString(",")
				lineBreakTo(len(stack))
			} else {
				writeIndent(len(stack))
			}
			return
		}
	}
	_ = valuePrefix

	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return sb.String(), err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{', '[':
				// prefix
				if len(stack) > 0 {
					top := stack[len(stack)-1]
					if top.isObject && top.afterKey {
						sb.WriteString(": ")
					} else if top.isObject && top.expectingKey {
						// shouldn't happen
					} else {
						// array element
						if top.count > 0 {
							sb.WriteString(",")
							lineBreakTo(len(stack))
						} else {
							writeIndent(len(stack))
						}
					}
				}
				sb.WriteString(currentPalette.yellow(string(t)))
				isObj := t == '{'
				stack = append(stack, &jsonFrame{isObject: isObj, expectingKey: isObj})
				if indentUnit != "" {
					sb.WriteString("\n")
				}
			case '}', ']':
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				if indentUnit != "" {
					sb.WriteString("\n")
					writeIndent(len(stack))
				}
				sb.WriteString(currentPalette.yellow(string(t)))
				completeValue()
			}
		case string:
			// key or value?
			if len(stack) > 0 && stack[len(stack)-1].isObject && stack[len(stack)-1].expectingKey && !stack[len(stack)-1].afterKey {
				// key
				top := stack[len(stack)-1]
				if top.count > 0 {
					sb.WriteString(",")
					lineBreakTo(len(stack))
				} else {
					writeIndent(len(stack))
				}
				sb.WriteString(currentPalette.blue(jsonEncodeString(t)))
				top.expectingKey = false
				top.afterKey = true
			} else {
				// value
				inContainer := len(stack) > 0
				if inContainer {
					top := stack[len(stack)-1]
					if top.isObject && top.afterKey {
						sb.WriteString(": ")
					} else if !top.isObject {
						if top.count > 0 {
							sb.WriteString(",")
							lineBreakTo(len(stack))
						} else {
							writeIndent(len(stack))
						}
					}
				}
				enc := jsonEncodeString(t)
				if inContainer {
					sb.WriteString(currentPalette.green(enc))
				} else {
					sb.WriteString(enc)
				}
				completeValue()
			}
		case json.Number:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			if inContainer {
				sb.WriteString(currentPalette.green(t.String()))
			} else {
				sb.WriteString(t.String())
			}
			completeValue()
		case bool:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			s := "false"
			if t {
				s = "true"
			}
			if inContainer {
				sb.WriteString(currentPalette.green(s))
			} else {
				sb.WriteString(s)
			}
			completeValue()
		case nil:
			inContainer := len(stack) > 0
			if inContainer {
				top := stack[len(stack)-1]
				if top.isObject && top.afterKey {
					sb.WriteString(": ")
				} else if !top.isObject {
					if top.count > 0 {
						sb.WriteString(",")
						lineBreakTo(len(stack))
					} else {
						writeIndent(len(stack))
					}
				}
			}
			if inContainer {
				sb.WriteString(currentPalette.green("null"))
			} else {
				sb.WriteString("null")
			}
			completeValue()
		default:
			// float64 if UseNumber not applied somewhere
			s := fmt.Sprintf("%v", tok)
			sb.WriteString(s)
			completeValue()
		}
	}
	return sb.String(), nil
}

