{"command":"cat > html.go <<'EOF'
package main

import (
	"html"
	"io"
	"strings"
)

// ---------- HTML tokenizer ----------

type htmlTokKind int

const (
	htText htmlTokKind = iota
	htStart
	htEnd
	htComment // raw full markup (<!--...-->, <!foo>, <?pi>)
	htDoctype // inner directive
)

type htmlToken struct {
	kind        htmlTokKind
	name        string
	attrs       []attrPair
	text        string
	raw         string // for comment
	directive   string // for doctype inner
	selfClosing bool
}

var voidTags = map[string]bool{
	"area": true, "base": true, "br": true, "col": true, "embed": true, "hr": true, "img": true, "input": true, "keygen": true, "link": true, "meta": true, "param": true, "source": true, "track": true, "wbr": true,
}

var rawTextTags = map[string]bool{
	"script": true, "style": true, "xmp": true, "iframe": true, "noembed": true, "noframes": true, "noscript": true, "plaintext": true,
}
var rcDataTags = map[string]bool{
	"textarea": true, "title": true,
}

func isHTMLSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f'
}
func isASCIILetter(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

type htmlScanner struct {
	s       string
	pos     int
	rawTag  string
	rawRC   bool
	pendingEnd *htmlToken
}

func newHTMLScanner(input string) *htmlScanner {
	return &htmlScanner{s: input}
}

func (sc *htmlScanner) next() (htmlToken, error) {
	if sc.pendingEnd != nil {
		tok := *sc.pendingEnd
		sc.pendingEnd = nil
		return tok, nil
	}
	for {
		if sc.rawTag != "" {
			tag := sc.rawTag
			rc := sc.rawRC
			if tag == "plaintext" {
				if sc.pos >= len(sc.s) {
					sc.rawTag = ""
					return htmlToken{}, io.EOF
				}
				text := sc.s[sc.pos:]
				sc.pos = len(sc.s)
				return htmlToken{kind: htText, text: text}, nil
			}
			// find end tag
			idx := findRawTextEnd(sc.s, sc.pos, tag)
			if idx < 0 {
				// rest as text
				text := sc.s[sc.pos:]
				sc.pos = len(sc.s)
				sc.rawTag = ""
				if rc {
					text = html.UnescapeString(text)
				}
				if text == "" {
					return htmlToken{}, io.EOF
				}
				return htmlToken{kind: htText, text: text}, nil
			}
			if idx > sc.pos {
				text := sc.s[sc.pos:idx]
				sc.pos = idx
				if rc {
					text = html.UnescapeString(text)
				}
				// clear raw so next call parses end tag; but remember to parse end
				sc.rawTag = ""
				return htmlToken{kind: htText, text: text}, nil
			}
			// at end tag, fall through to parse it
			sc.rawTag = ""
		}
		if sc.pos >= len(sc.s) {
			return htmlToken{}, io.EOF
		}
		// text up to <
		if sc.s[sc.pos] != '<' {
			start := sc.pos
			nxt := strings.IndexByte(sc.s[start:], '<')
			var text string
			if nxt < 0 {
				text = sc.s[start:]
				sc.pos = len(sc.s)
			} else {
				text = sc.s[start : start+nxt]
				sc.pos = start + nxt
			}
			return htmlToken{kind: htText, text: html.UnescapeString(text)}, nil
		}
		// sc.s[pos]=='<'
		rest := sc.s[sc.pos:]
		if strings.HasPrefix(rest, "<!--") {
			// comment
			end := strings.Index(rest[4:], "-->")
			var raw string
			if end < 0 {
				raw = rest
				sc.pos = len(sc.s)
			} else {
				raw = rest[:4+end+3]
				sc.pos += len(raw)
			}
			return htmlToken{kind: htComment, raw: raw}, nil
		}
		if len(rest) >= 2 && rest[1] == '!' {
			// doctype or bogus
			// check doctype (case-insens)
			if len(rest) >= 9 && strings.EqualFold(rest[:9], "<!doctype") {
				gt := findTagEnd(sc.s, sc.pos)
				if gt < 0 {
					raw := rest
					sc.pos = len(sc.s)
					inner := strings.TrimPrefix(raw, "<!")
					// remove trailing > if present
					inner = strings.TrimSuffix(inner, ">")
					return htmlToken{kind: htDoctype, directive: inner}, nil
				}
				inner := sc.s[sc.pos+2 : gt]
				sc.pos = gt + 1
				return htmlToken{kind: htDoctype, directive: inner}, nil
			}
			// bogus comment until >
			gt := strings.IndexByte(rest, '>')
			var raw string
			if gt < 0 {
				raw = rest
				sc.pos = len(sc.s)
			} else {
				raw = rest[:gt+1]
				sc.pos += gt + 1
			}
			return htmlToken{kind: htComment, raw: raw}, nil
		}
		if len(rest) >= 2 && rest[1] == '?' {
			gt := strings.IndexByte(rest, '>')
			var raw string
			if gt < 0 {
				raw = rest
				sc.pos = len(sc.s)
			} else {
				raw = rest[:gt+1]
				sc.pos += gt + 1
			}
			return htmlToken{kind: htComment, raw: raw}, nil
		}
		if len(rest) >= 2 && rest[1] == '/' {
			if len(rest) >= 3 && isASCIILetter(rest[2]) {
				// end tag
				i := sc.pos + 2
				start := i
				for i < len(sc.s) && !isHTMLSpace(sc.s[i]) && sc.s[i] != '/' && sc.s[i] != '>' {
					i++
				}
				name := strings.ToLower(sc.s[start:i])
				gt := findTagEnd(sc.s, sc.pos)
				if gt < 0 {
					sc.pos = len(sc.s)
					return htmlToken{}, io.EOF
				}
				sc.pos = gt + 1
				return htmlToken{kind: htEnd, name: name}, nil
			}
			if len(rest) >= 3 && rest[2] == '>' {
				sc.pos += 3
				continue
			}
			// bogus comment
			gt := strings.IndexByte(rest, '>')
			var raw string
			if gt < 0 {
				raw = rest
				sc.pos = len(sc.s)
			} else {
				raw = rest[:gt+1]
				sc.pos += gt + 1
			}
			return htmlToken{kind: htComment, raw: raw}, nil
		}
		if len(rest) >= 2 && isASCIILetter(rest[1]) {
			tok, ok := sc.parseStartTag()
			if !ok {
				// incomplete tag at EOF: discard
				return htmlToken{}, io.EOF
			}
			return tok, nil
		}
		// stray '<' as text
		start := sc.pos
		nxt := strings.IndexByte(sc.s[start+1:], '<')
		var text string
		if nxt < 0 {
			text = sc.s[start:]
			sc.pos = len(sc.s)
		} else {
			text = sc.s[start : start+1+nxt]
			sc.pos = start + 1 + nxt
		}
		return htmlToken{kind: htText, text: html.UnescapeString(text)}, nil
	}
}

func findTagEnd(s string, start int) int {
	// find > respecting quotes (single/double)
	var quote byte
	for i := start; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			continue
		}
		if c == '>' {
			return i
		}
	}
	return -1
}

func findRawTextEnd(s string, from int, tag string) int {
	// search </tag case-insens with boundary
	lower := strings.ToLower(s[from:])
	needle := "</" + tag
	idx := 0
	for {
		j := strings.Index(lower[idx:], needle)
		if j < 0 {
			return -1
		}
		pos := idx + j
		after := from + pos + len(needle)
		if after >= len(s) {
			return from + pos
		}
		c := s[after]
