				gt := findTagEnd(sc.s, sc.pos)
				if gt < 0 {
					sc.pos = len(sc.s)
					return htmlToken{}, io.EOF
				}
				sc.pos = gt + 1
				return htmlToken{kind: htEnd, name: name}, nil
