			if len(rest) >= 3 && rest[2] == '>' {
				sc.pos += 3
				continue
			}
			// bogus comment
			gt := strings.IndexByte(rest, '>')
			var raw string
			if gt < 0 {
				raw = rest
				sc.pos = len(sc.s)
			} else {
				raw = rest[:gt+1]
				sc.pos += gt + 1
			}
			return htmlToken{kind: htComment, raw: raw}, nil
		}
