		start := sc.pos
		nxt := strings.IndexByte(sc.s[start+1:], '<')
		var text string
		if nxt < 0 {
			text = sc.s[start:]
			sc.pos = len(sc.s)
		} else {
			text = sc.s[start : start+1+nxt]
			sc.pos = start + 1 + nxt
		}
