}

func findTagEnd(s string, start int) int {
	// find > respecting quotes (single/double)
	var quote byte
	for i := start; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			continue
		}
		if c == '>' {
			return i
		}
	}
	return -1
}

func findRawTextEnd(s string, from int, tag string) int {
	// search </tag case-insens with boundary
	lower := strings.ToLower(s[from:])
	needle := "</" + tag
	idx := 0
	for {
		j := strings.Index(lower[idx:], needle)
		if j < 0 {
			return -1
		}
		pos := idx + j
		after := from + pos + len(needle)
		if after >= len(s) {
			return from + pos
		}
		c := s[after]
		if isHTMLSpace(c) || c == '/' || c == '>' {
			return from + pos
		}
		idx = pos + 1
	}
}

func (sc *htmlScanner) parseStartTag() (htmlToken, bool) {
	i := sc.pos + 1
	start := i
	for i < len(sc.s) && !isHTMLSpace(sc.s[i]) && sc.s[i] != '/' && sc.s[i] != '>' {
		i++
	}
	name := strings.ToLower(sc.s[start:i])
	var attrs []attrPair
	selfClosing := false
	for {
		// skip spaces
		for i < len(sc.s) && isHTMLSpace(sc.s[i]) {
			i++
		}
		if i >= len(sc.s) {
			return htmlToken{}, false
		}
		c := sc.s[i]
		if c == '>' {
			i++
			break
		}
		if c == '/' {
			if i+1 < len(sc.s) && sc.s[i+1] == '>' {
				selfClosing = true
				i += 2
				break
			}
			i++
			continue
		}
		// attr name
		aStart := i
		if sc.s[i] == '=' {
			// '=' as first char of name per original tokenizer quirk
			i++
		}
		for i < len(sc.s) && !isHTMLSpace(sc.s[i]) && sc.s[i] != '=' && sc.s[i] != '/' && sc.s[i] != '>' {
			i++
		}
		attrName := strings.ToLower(sc.s[aStart:i])
		// skip spaces
		for i < len(sc.s) && isHTMLSpace(sc.s[i]) {
			i++
		}
		value := ""
		if i < len(sc.s) && sc.s[i] == '=' {
			i++
			for i < len(sc.s) && isHTMLSpace(sc.s[i]) {
				i++
			}
			if i >= len(sc.s) {
				return htmlToken{}, false
			}
			if sc.s[i] == '"' || sc.s[i] == '\'' {
				q := sc.s[i]
				i++
				vStart := i
				end := strings.IndexByte(sc.s[i:], q)
				if end < 0 {
					return htmlToken{}, false
				}
				value = sc.s[vStart : vStart+end]
				i = vStart + end + 1
			} else if sc.s[i] == '>' {
				value = ""
				// don't consume >
			} else {
				vStart := i
				for i < len(sc.s) && !isHTMLSpace(sc.s[i]) && sc.s[i] != '>' {
					i++
				}
				value = sc.s[vStart:i]
			}
			value = html.UnescapeString(value)
		}
		if attrName != "" {
			attrs = append(attrs, attrPair{Name: attrName, Value: value})
		} else if i == aStart {
			// avoid infinite loop
			i++
		}
	}
	sc.pos = i
	tok := htmlToken{kind: htStart, name: name, attrs: attrs, selfClosing: selfClosing}
	if !selfClosing {
		if rawTextTags[name] {
			sc.rawTag = name
			sc.rawRC = false
			if name == "plaintext" {
				// stays raw
			}
		} else if rcDataTags[name] {
			sc.rawTag = name
			sc.rawRC = true
		}
	}
	return tok, true
}

// ------- HTML formatter event source -------

type htmlEventSource struct {
	sc *htmlScanner
}

func (h *htmlEventSource) next() (fmtEvent, error) {
	tok, err := h.sc.next()
	if err != nil {
		return fmtEvent{}, err
	}
	switch tok.kind {
	case htText:
		return fmtEvent{kind: evText, text: tok.text}, nil
	case htStart:
		if tok.selfClosing || voidTags[tok.name] {
			return fmtEvent{kind: evCompletedStart, name: tok.name, attrs: tok.attrs}, nil
		}
		return fmtEvent{kind: evStart, name: tok.name, attrs: tok.attrs}, nil
	case htEnd:
		return fmtEvent{kind: evEnd, name: tok.name}, nil
	case htComment:
		return fmtEvent{kind: evComment, commentRaw: tok.raw, htmlComment: true}, nil
	case htDoctype:
		d := tok.directive
		isDT := len(d) >= 7 && strings.EqualFold(d[:7], "doctype")
		// In HTML mode, doctype tokens always go through doctype rendering even if malformed?
		// The scanner only produces htDoctype for doctype prefix, so isDT true.
		return fmtEvent{kind: evDirective, directive: d, isDoctype: isDT}, nil
	}
	return fmtEvent{kind: evText, text: ""}, nil
}

func formatHTMLString(input string) (string, error) {
	return formatWithSource(&htmlEventSource{sc: newHTMLScanner(input)}, currentOptions.indentUnit, true)
}
