					push(node)
				}
				continue
			}
			// body content
			if !bodyStarted {
				toBody()
				bodyStarted = true
			} else if len(stack) == 0 {
				toBody()
			}
			// implicit closes
			applyImplicitClose(&stack, name)
			cur := current()
			if cur == nil {
				toBody()
				cur = current()
			}
			node := &domNode{Type: nodeElement, QName: name, Local: name, Parent: cur, Order: order}
			order++
			for _, a := range tok.attrs {
				an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: node, Data: a.Value, Order: order}
				order++
				node.Attrs = append(node.Attrs, an)
			}
			cur.Children = append(cur.Children, node)
			// determine if push
			inForeign := false
			for _, sn := range stack {
				if sn.Local == "svg" || sn.Local == "math" {
					inForeign = true
					break
				}
			}
			if name == "svg" || name == "math" {
				inForeign = true
			}
			if voidTags[name] {
				// no push
			} else if tok.selfClosing && inForeign {
				// no push
			} else {
				push(node)
			}
		case htEnd:
			name := tok.name
			if name == "html" {
				// pop all
				stack = nil
				continue
			}
			if name == "body" {
				if bodyEl != nil {
					popTo(bodyEl)
				}
				continue
			}
			if name == "head" {
				if headEl != nil {
					popTo(headEl)
				}
				continue
			}
			if voidTags[name] {
				// </br> treated as <br> in HTML spec, but for CSS tree ignore mostly
				if name == "br" {
					// create a br element
					cur := current()
					if cur != nil {
						node := &domNode{Type: nodeElement, QName: "br", Local: "br", Parent: cur, Order: order}
						order++
						cur.Children = append(cur.Children, node)
					}
				}
				continue
			}
			// find matching open
			found := -1
			for i := len(stack) - 1; i >= 0; i-- {
				if stack[i].Local == name {
					found = i
					break
				}
			}
			if found >= 0 {
				stack = stack[:found]
			}
			// else ignore
		}
	}
	ensureBody(nil)
	return doc
}

func makeHTMLElement(tok htmlToken, order int, parent *domNode) *domNode {
	// not really used except placeholder
	n := &domNode{Type: nodeElement, QName: tok.name, Local: tok.name, Parent: parent, Order: order}
	return n
}

func applyImplicitClose(stack *[]*domNode, newTag string) {
	s := *stack
	closeTag := func(tags ...string) {
		// pop up to and including nearest matching tag if present in stack above body/html boundaries
		for i := len(s) - 1; i >= 0; i-- {
			if s[i].Local == "body" || s[i].Local == "html" {
				break
			}
			for _, t := range tags {
				if s[i].Local == t {
					s = s[:i]
					*stack = s
					return
				}
			}
		}
	}
	switch newTag {
	case "li":
		closeTag("li")
	case "dt", "dd":
		closeTag("dt", "dd")
	case "option":
		closeTag("option")
	case "optgroup":
		closeTag("option", "optgroup")
	case "tr":
		closeTag("tr", "td", "th")
	case "td", "th":
		closeTag("td", "th")
	case "thead", "tbody", "tfoot":
		closeTag("thead", "tbody", "tfoot", "tr", "td", "th")
	case "button":
		closeTag("button")
	case "h1", "h2", "h3", "h4", "h5", "h6":
		closeTag("h1", "h2", "h3", "h4", "h5", "h6")
	}
	// block elements close p
	blockTags := map[string]bool{
		"address": true, "article": true, "aside": true, "blockquote": true, "details": true, "div": true, "dl": true, "fieldset": true, "figcaption": true, "figure": true, "footer": true, "form": true, "h1": true, "h2": true, "h3": true, "h4": true, "h5": true, "h6": true, "header": true, "hgroup": true, "hr": true, "main": true, "menu": true, "nav": true, "ol": true, "p": true, "pre": true, "section": true, "table": true, "ul": true,
	}
	if blockTags[newTag] {
		// close p if open
		s = *stack
		for i := len(s) - 1; i >= 0; i-- {
			if s[i].Local == "body" || s[i].Local == "html" || s[i].Local == "button" {
				break
			}
			if s[i].Local == "p" {
				s = s[:i]
				*stack = s
				break
			}
		}
	}
	if newTag == "p" {
		// already handled as block (closes p)
	}
}

// ---------- serialization ----------

func serializeXMLNode(n *domNode) string {
	var b strings.Builder
	serializeXMLNodeInto(&b, n)
	return b.String()
}
func serializeXMLNodeInto(b *strings.Builder, n *domNode) {
	switch n.Type {
	case nodeDocument:
		b.WriteString(`<?xml version="1.0"?>`)
		for _, c := range n.Children {
			serializeXMLNodeInto(b, c)
		}
	case nodeElement:
		b.WriteString("<" + n.QName)
		for _, a := range n.Attrs {
			b.WriteString(" " + a.QName + "=\"" + escapeAttrValue(a.Data) + "\"")
		}
		b.WriteString(">")
		for _, c := range n.Children {
			serializeXMLNodeInto(b, c)
		}
		b.WriteString("</" + n.QName + ">")
	case nodeText:
		b.WriteString(escapeTextXML(n.Data))
	case nodeComment:
		b.WriteString("<!--" + n.Data + "-->")
	case nodePI:
		if n.Data != "" {
			b.WriteString("<?" + n.PITarget + " " + n.Data + "?>")
		} else {
			b.WriteString("<?" + n.PITarget + "?>")
		}
	case nodeDirective:
		b.WriteString("<!" + n.Data + ">")
	case nodeAttr:
		b.WriteString("<" + n.Local + ">" + escapeTextXML(n.Data) + "</" + n.Local + ">")
	}
}

func serializeHTMLNode(n *domNode) string {
	var b strings.Builder
	serializeHTMLNodeInto(&b, n)
	return b.String()
}
func serializeHTMLNodeInto(b *strings.Builder, n *domNode) {
	switch n.Type {
	case nodeDocument:
		for _, c := range n.Children {
			serializeHTMLNodeInto(b, c)
		}
	case nodeElement:
		b.WriteString("<" + n.QName)
		for _, a := range n.Attrs {
			b.WriteString(" " + a.QName + "=\"" + html.EscapeString(a.Data) + "\"")
		}
		b.WriteString(">")
		for _, c := range n.Children {
			serializeHTMLNodeInto(b, c)
		}
		b.WriteString("</" + n.QName + ">")
	case nodeText:
		// net/html escapes text (&#34; etc) - html.EscapeString does <>&'"
		b.WriteString(html.EscapeString(n.Data))
	case nodeComment:
		b.WriteString("<!--" + n.Data + "-->")
	case nodeDirective:
		b.WriteString("<!" + n.Data + ">")
	case nodePI:
		b.WriteString("<?" + n.PITarget + " " + n.Data + ">")
	}
}
