{"command":"cat > dom.go <<'EOF'
package main

import (
	"encoding/xml"
	"errors"
	"html"
	"io"
	"strings"
)

type nodeType int

const (
	nodeDocument nodeType = iota
	nodeElement
	nodeText
	nodeComment
	nodePI
	nodeDirective
	nodeAttr
)

type domNode struct {
	Type     nodeType
	QName    string
	Local    string
	Prefix   string
	NSURI    string
	Attrs    []*domNode // attribute nodes (Type nodeAttr)
	Children []*domNode
	Parent   *domNode
	Data     string // text/comment/pi-inst/directive/attr value
	PITarget string
	Order    int
}

func (n *domNode) attrValue(name string) (string, bool) {
	for _, a := range n.Attrs {
		// CSS attr lookup uses exact stored name (lowercase for html)
		if a.QName == name {
			return a.Data, true
		}
		// for xml nodes, attr nodes stored QName; also allow Local match? caller handles
	}
	return "", false
}
func (n *domNode) getAttrExact(name string) (string, bool) {
	for _, a := range n.Attrs {
		if a.QName == name {
			return a.Data, true
		}
	}
	return "", false
}

func innerText(n *domNode) string {
	if n == nil {
		return ""
	}
	switch n.Type {
	case nodeDocument:
		return ""
	case nodeText, nodeComment:
		return n.Data
	case nodeAttr:
		return n.Data
	case nodePI, nodeDirective:
		return n.Data
	default:
		var b strings.Builder
		for _, c := range n.Children {
			if c.Type == nodeText {
				b.WriteString(c.Data)
			} else if c.Type == nodeElement {
				b.WriteString(innerText(c))
			} else if c.Type == nodeDocument {
				b.WriteString(innerText(c))
			}
			// comments/pi/directive excluded
		}
		return b.String()
	}
}

func stringValue(n *domNode) string {
	if n == nil {
		return ""
	}
	switch n.Type {
	case nodeText, nodeComment:
		return n.Data
	case nodeAttr:
		return n.Data
	case nodePI:
		return n.Data
	default:
		var b strings.Builder
		var walk func(x *domNode)
		walk = func(x *domNode) {
			for _, c := range x.Children {
				if c.Type == nodeText {
					b.WriteString(c.Data)
				} else {
					walk(c)
				}
			}
		}
		walk(n)
		return b.String()
	}
}

var errInvalidXMLDocument = errors.New("xmlquery: invalid XML document")

func parseXMLDocument(content []byte, strict bool) (*domNode, error) {
	dec := xml.NewDecoder(strings.NewReader(string(content)))
	dec.Strict = strict
	doc := &domNode{Type: nodeDocument}
	order := 0
	doc.Order = order
	order++
	// stack of nodes and scopes
	type stackItem struct {
		node  *domNode
		scope *nsScope
	}
	stack := []stackItem{{node: doc, scope: nil}}
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			parent := stack[len(stack)-1]
			scope := parent.scope.cloneWithDecls(t.Attr)
			qname := qualifiedName(t.Name.Space, t.Name.Local, scope, false)
			prefix, nsuri := derivePrefixURI(t.Name.Space, scope, false)
			el := &domNode{Type: nodeElement, QName: qname, Local: t.Name.Local, Prefix: prefix, NSURI: nsuri, Parent: parent.node, Order: order}
			order++
			// attributes
			for _, a := range t.Attr {
				aq := attrQualifiedName(a, scope)
				aprefix, ansuri := deriveAttrPrefixURI(a, scope)
				alocal := a.Name.Local
				// For xmlns:x, Local is x; for p:a, Local is a
				an := &domNode{Type: nodeAttr, QName: aq, Local: alocal, Prefix: aprefix, NSURI: ansuri, Parent: el, Data: a.Value, Order: order}
				order++
				el.Attrs = append(el.Attrs, an)
			}
			parent.node.Children = append(parent.node.Children, el)
			stack = append(stack, stackItem{node: el, scope: scope})
		case xml.EndElement:
			if len(stack) > 1 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			if len(t) == 0 {
				continue
			}
			parent := stack[len(stack)-1].node
			tn := &domNode{Type: nodeText, Data: string(t), Parent: parent, Order: order}
			order++
			parent.Children = append(parent.Children, tn)
		case xml.Comment:
			parent := stack[len(stack)-1].node
			tn := &domNode{Type: nodeComment, Data: string(t), Parent: parent, Order: order}
			order++
			parent.Children = append(parent.Children, tn)
		case xml.ProcInst:
			parent := stack[len(stack)-1].node
			tn := &domNode{Type: nodePI, PITarget: t.Target, Data: string(t.Inst), Parent: parent, Order: order}
			order++
			parent.Children = append(parent.Children, tn)
		case xml.Directive:
			parent := stack[len(stack)-1].node
			tn := &domNode{Type: nodeDirective, Data: string(t), Parent: parent, Order: order}
			order++
			parent.Children = append(parent.Children, tn)
		}
	}
	hasRoot := false
	for _, c := range doc.Children {
		if c.Type == nodeElement {
			hasRoot = true
			break
		}
	}
	if !hasRoot {
		return nil, errInvalidXMLDocument
	}
	return doc, nil
}

func derivePrefixURI(space string, scope *nsScope, isAttr bool) (string, string) {
	if space == "" {
		return "", ""
	}
	if space == "xmlns" {
		return "xmlns", "http://www.w3.org/2000/xmlns/"
	}
	if space == "http://www.w3.org/XML/1998/namespace" {
		return "xml", space
	}
	if scope != nil {
		if !isAttr && scope.defaultURI == space {
			return "", space
		}
		if p, ok := scope.prefixByURI[space]; ok && p != "" {
			return p, space
		}
	}
	if !strings.Contains(space, "/") && !strings.Contains(space, ":") && !strings.Contains(space, ".") {
		// undeclared prefix
		return space, ""
	}
	return "", space
}
func deriveAttrPrefixURI(a xml.Attr, scope *nsScope) (string, string) {
	if a.Name.Space == "xmlns" {
		return "xmlns", "http://www.w3.org/2000/xmlns/"
	}
	if a.Name.Space == "" {
		return "", ""
	}
	return derivePrefixURI(a.Name.Space, scope, true)
}

// ---------- HTML document parsing for CSS ----------

func parseHTMLDocument(content []byte) *domNode {
	doc := &domNode{Type: nodeDocument, Order: 0}
	order := 1
	sc := newHTMLScanner(string(content))
	// State for building
	var htmlEl, headEl, bodyEl *domNode
	// stack of open nodes (insertion stack) - starts empty
	var stack []*domNode
	current := func() *domNode {
		if len(stack) > 0 {
			return stack[len(stack)-1]
		}
		return nil
	}
	push := func(n *domNode) { stack = append(stack, n) }
	popTo := func(n *domNode) {
		for i := len(stack) - 1; i >= 0; i-- {
			if stack[i] == n {
				stack = stack[:i]
				return
			}
		}
	}
	ensureHTML := func(attrs []attrPair) *domNode {
		if htmlEl == nil {
			htmlEl = &domNode{Type: nodeElement, QName: "html", Local: "html", Parent: doc, Order: order}
			order++
			doc.Children = append(doc.Children, htmlEl)
			if attrs != nil {
				for _, a := range attrs {
					an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: htmlEl, Data: a.Value, Order: order}
					order++
					htmlEl.Attrs = append(htmlEl.Attrs, an)
				}
			}
		} else if attrs != nil {
			// merge missing
			for _, a := range attrs {
				if _, ok := htmlEl.getAttrExact(a.Name); !ok {
					an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: htmlEl, Data: a.Value, Order: order}
					order++
					htmlEl.Attrs = append(htmlEl.Attrs, an)
				}
			}
		}
		return htmlEl
	}
	ensureHead := func(attrs []attrPair) *domNode {
		ensureHTML(nil)
		if headEl == nil {
			headEl = &domNode{Type: nodeElement, QName: "head", Local: "head", Parent: htmlEl, Order: order}
			order++
			// insert before body if present
			if bodyEl != nil {
				// find body index
				idx := -1
				for i, c := range htmlEl.Children {
					if c == bodyEl {
						idx = i
						break
					}
				}
				if idx >= 0 {
					htmlEl.Children = append(htmlEl.Children, nil)
					copy(htmlEl.Children[idx+1:], htmlEl.Children[idx:])
					htmlEl.Children[idx] = headEl
				} else {
					htmlEl.Children = append(htmlEl.Children, headEl)
				}
			} else {
				htmlEl.Children = append(htmlEl.Children, headEl)
			}
			if attrs != nil {
				for _, a := range attrs {
					an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: headEl, Data: a.Value, Order: order}
					order++
					headEl.Attrs = append(headEl.Attrs, an)
				}
			}
		}
		return headEl
	}
	ensureBody := func(attrs []attrPair) *domNode {
		ensureHead(nil)
		if bodyEl == nil {
			bodyEl = &domNode{Type: nodeElement, QName: "body", Local: "body", Parent: htmlEl, Order: order}
			order++
			htmlEl.Children = append(htmlEl.Children, bodyEl)
			if attrs != nil {
				for _, a := range attrs {
					an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: bodyEl, Data: a.Value, Order: order}
					order++
					bodyEl.Attrs = append(bodyEl.Attrs, an)
				}
			}
		} else if attrs != nil {
			for _, a := range attrs {
				if _, ok := bodyEl.getAttrExact(a.Name); !ok {
					an := &domNode{Type: nodeAttr, QName: a.Name, Local: a.Name, Parent: bodyEl, Data: a.Value, Order: order}
					order++
					bodyEl.Attrs = append(bodyEl.Attrs, an)
				}
			}
		}
		return bodyEl
	}
	// helper to reset stack to body context
	toBody := func() {
		ensureBody(nil)
		stack = []*domNode{htmlEl, bodyEl}
	}
	toHead := func() {
		ensureHead(nil)
		stack = []*domNode{htmlEl, headEl}
	}
	appendNode := func(parent *domNode, n *domNode) {
		n.Parent = parent
		if n.Order == 0 {
			n.Order = order
			order++
		}
		parent.Children = append(parent.Children, n)
	}
	_ = appendNode

	headTags := map[string]bool{
		"base": true, "basefont": true, "bgsound": true, "link": true, "meta": true, "title": true, "noscript": true, "noframes": true, "script": true, "style": true, "template": true,
	}
	bodyStarted := false

	for {
		tok, err := sc.next()
		if err != nil {
			break
		}
		switch tok.kind {
		case htDoctype:
			dn := &domNode{Type: nodeDirective, Data: tok.directive, Parent: doc, Order: order}
			order++
			// insert before html if exists
			if htmlEl != nil {
				// insert at beginning
				doc.Children = append([]*domNode{dn}, doc.Children...)
			} else {
				doc.Children = append(doc.Children, dn)
			}
		case htComment:
			// comment raw: extract inner if <!-- -->
			data := tok.raw
			inner := data
			if strings.HasPrefix(data, "<!--") && strings.HasSuffix(data, "-->") && len(data) >= 7 {
				inner = data[4 : len(data)-3]
			} else {
				// bogus comment: strip < and >
				inner = strings.TrimSuffix(strings.TrimPrefix(data, "<"), ">")
				// keep as comment node data? not critical
			}
			cn := &domNode{Type: nodeComment, Data: inner, Parent: nil, Order: order}
			order++
			if cur := current(); cur != nil {
				cn.Parent = cur
				cur.Children = append(cur.Children, cn)
			} else if bodyStarted || bodyEl != nil {
				// after body?
				cn.Parent = bodyEl
				if bodyEl != nil {
					bodyEl.Children = append(bodyEl.Children, cn)
				}
			} else if htmlEl != nil {
				cn.Parent = htmlEl
				htmlEl.Children = append(htmlEl.Children, cn)
			} else {
				cn.Parent = doc
				doc.Children = append(doc.Children, cn)
			}
		case htText:
			if tok.text == "" {
				continue
			}
			cur := current()
			// if stack is at html/head level and text is non-whitespace and not inside a head element like title
			inHeadElement := false
			if cur != nil && cur != headEl && cur != htmlEl && cur != bodyEl && cur != doc {
				// inside some element (title/p/etc)
				inHeadElement = true
			}
			if cur == nil || cur == doc || cur == htmlEl || cur == headEl {
				if strings.TrimSpace(tok.text) == "" {
					// whitespace before body - attach to head if exists else ignore structure
					if !bodyStarted {
						// put in head
						ensureHead(nil)
						tn := &domNode{Type: nodeText, Data: tok.text, Parent: headEl, Order: order}
						order++
						headEl.Children = append(headEl.Children, tn)
						continue
					}
					// after body start, will fall through
				} else if !inHeadElement {
					// start body
					if !bodyStarted {
						toBody()
						bodyStarted = true
						cur = current()
					}
				}
			}
			if cur == nil || cur == doc || cur == htmlEl || cur == headEl {
				if bodyEl == nil {
					toBody()
					bodyStarted = true
				} else if !bodyStarted {
					toBody()
					bodyStarted = true
				}
				cur = current()
			}
			// merge with previous text sibling if adjacent?
			tn := &domNode{Type: nodeText, Data: tok.text, Parent: cur, Order: order}
			order++
			cur.Children = append(cur.Children, tn)
		case htStart:
			name := tok.name
			if name == "html" {
				ensureHTML(tok.attrs)
				stack = []*domNode{htmlEl}
				continue
			}
			if name == "head" {
				if headEl == nil && !bodyStarted {
					ensureHead(tok.attrs)
					stack = []*domNode{htmlEl, headEl}
				}
				continue
			}
			if name == "body" {
				if bodyEl == nil {
					ensureBody(tok.attrs)
				} else {
					ensureBody(tok.attrs)
				}
				stack = []*domNode{htmlEl, bodyEl}
				bodyStarted = true
				continue
			}
			// head content before body
			if !bodyStarted && headTags[name] {
				// ensure head context unless currently inside an element in body etc
				if current() == nil || current() == doc || current() == htmlEl || current() == headEl {
					toHead()
				}
				// create element under current (head)
				el := makeHTMLElement(tok, order, current())
				order = el.Order + 1 // makeHTMLElement assigns orders internally? We'll manage below
				// Instead create manually:
				// (makeHTMLElement not used; reconstruct)
				_ = el
				// manual:
				cur := current()
				node := &domNode{Type: nodeElement, QName: name, Local: name, Parent: cur, Order: order}
				order++
				for _, a := range tok.attrs {
