		closeTag("li")
	case "dt", "dd":
		closeTag("dt", "dd")
	case "option":
		closeTag("option")
	case "optgroup":
		closeTag("option", "optgroup")
	case "tr":
		closeTag("tr", "td", "th")
	case "td", "th":
		closeTag("td", "th")
	case "thead", "tbody", "tfoot":
		closeTag("thead", "tbody", "tfoot", "tr", "td", "th")
	case "button":
		closeTag("button")
	case "h1", "h2", "h3", "h4", "h5", "h6":
		closeTag("h1", "h2", "h3", "h4", "h5", "h6")
	}
