				p.arityErr = "xpath: count(node-sets) function must with have parameters node-sets"
			} else if name == "substring" {
				p.arityErr = "xpath: substring function must have at least two parameter"
			} else {
				p.arityErr = "expression must evaluate to a node-set"
			}
		}
	}
	fc := &xpFuncCall{name: name, args: args}
	// function result may be filtered / path-continued: e.g. string(...) no, but (in xpath) count(...) is final
	// Handle predicates following e.g. substring(...)[1] is unusual; also path continuation for node-set functions id(...)
	if p.isOp("[") {
		var preds []xpExpr
		for p.isOp("[") {
			pr, err := p.parsePredicate()
			if err != nil { return nil, err }
			preds = append(preds, pr)
		}
		if p.isOp("/") || p.isOp("//") {
			steps, err := p.parsePathContinuation()
			if err != nil { return nil, err }
			return &xpFilter{base: fc, preds: preds, steps: steps}, nil
		}
		return &xpFilter{base: fc, preds: preds}, nil
	}
	if p.isOp("/") || p.isOp("//") {
		steps, err := p.parsePathContinuation()
		if err != nil { return nil, err }
		return &xpFilter{base: fc, steps: steps}, nil
	}
	return fc, nil
}

func (p *xpParser) parsePathContinuation() ([]*xpStep, error) {
	// current is / or //
	var steps []*xpStep
	for p.isOp("/") || p.isOp("//") {
		sep := p.next().val
		if sep == "//" {
			steps = append(steps, &xpStep{axis: "descendant-or-self", testKind: "node"})
		}
		st, err := p.parseStep()
		if err != nil { return nil, err }
		steps = append(steps, st)
	}
	return steps, nil
}

func (p *xpParser) atStepStart() bool {
	t := p.peek()
	if t.typ == "name" {
		return true
	}
	if t.typ == "op" && (t.val == "*" || t.val == "@" || t.val == "." || t.val == "..") {
		return true
	}
	return false
}

func (p *xpParser) parseSteps() ([]*xpStep, error) {
	var steps []*xpStep
	st, err := p.parseStep()
	if err != nil { return nil, err }
	steps = append(steps, st)
	cont, err := p.parseStepContinuations()
	if err != nil { return nil, err }
	steps = append(steps, cont...)
	return steps, nil
}
func (p *xpParser) parseStepsAfterFirst() ([]*xpStep, error) {
	// after //, we already consumed separator; parse one step plus continuations
	return p.parseSteps()
}
func (p *xpParser) parseStepContinuations() ([]*xpStep, error) {
	var steps []*xpStep
	for p.isOp("/") || p.isOp("//") {
		sep := p.next().val
		if sep == "//" {
			steps = append(steps, &xpStep{axis: "descendant-or-self", testKind: "node"})
		}
		st, err := p.parseStep()
		if err != nil { return nil, err }
		steps = append(steps, st)
	}
	return steps, nil
}

func (p *xpParser) parsePredicate() (xpExpr, error) {
	// assume '[' current
	p.next()
	e, err := p.parseExpr()
	if err != nil { return nil, err }
	if !p.expectOp("]") {
		return nil, fmt.Errorf("expected ]")
	}
	return e, nil
}

func (p *xpParser) parseStep() (*xpStep, error) {
	// Abbreviations
	if p.isOp(".") {
		p.next()
		st := &xpStep{axis: "self", testKind: "node"}
		// predicates following? '.' then [..] possible
		for p.isOp("[") {
			pr, err := p.parsePredicate()
			if err != nil { return nil, err }
			st.preds = append(st.preds, pr)
		}
		return st, nil
	}
	if p.isOp("..") {
		p.next()
		st := &xpStep{axis: "parent", testKind: "node"}
		for p.isOp("[") {
			pr, err := p.parsePredicate()
			if err != nil { return nil, err }
			st.preds = append(st.preds, pr)
		}
		return st, nil
	}
	axis := "child"
	if p.isOp("@") {
		p.next()
		axis = "attribute"
		// node test follows
		st, err := p.parseNodeTest(axis)
		if err != nil { return nil, err }
		st.axis = axis
		for p.isOp("[") {
			pr, err := p.parsePredicate()
			if err != nil { return nil, err }
			st.preds = append(st.preds, pr)
		}
		return st, nil
	}
	// axis::test form: name '::'
	if p.peek().typ == "name" && p.peekAt(1).typ == "op" && p.peekAt(1).val == "::" {
		axis = p.next().val
		p.next() // ::
		st, err := p.parseNodeTest(axis)
		if err != nil { return nil, err }
		st.axis = axis
		for p.isOp("[") {
			pr, err := p.parsePredicate()
			if err != nil { return nil, err }
			st.preds = append(st.preds, pr)
		}
		return st, nil
	}
	// plain node test with child axis
	st, err := p.parseNodeTest(axis)
	if err != nil { return nil, err }
	st.axis = axis
	for p.isOp("[") {
		pr, err := p.parsePredicate()
		if err != nil { return nil, err }
		st.preds = append(st.preds, pr)
	}
	return st, nil
}

func (p *xpParser) parseNodeTest(axis string) (*xpStep, error) {
	if p.isOp("*") {
		p.next()
		return &xpStep{testKind: "*"}, nil
	}
	if p.peek().typ == "name" {
		name := p.peek().val
		// node test function?
		if isNodeTestName(name) && p.peekAt(1).typ == "op" && p.peekAt(1).val == "(" {
			p.next() // name
			p.next() // (
			st := &xpStep{}
			switch name {
			case "text":
				st.testKind = "text"
			case "comment":
				st.testKind = "comment"
			case "node":
				st.testKind = "node"
			case "processing-instruction":
				st.testKind = "pi"
				// optional literal
				if p.peek().typ == "str" {
					st.piArg = p.next().val
					st.hasPIArg = true
				}
			}
			if !p.expectOp(")") {
				return nil, fmt.Errorf("expected ) in node test")
			}
			return st, nil
		}
		// qualified name: name [ ':' (name|*) ]  -- ':' comes as ??? lexer must emit it
		// Our lexer: ':' is included via op set extension below; check peek
		fullName := p.next().val
		local := fullName
		prefix := ""
		if p.peek().typ == "op" && p.peek().val == ":" {
			p.next()
			prefix = fullName
			if p.isOp("*") {
				p.next()
				return &xpStep{testKind: "*", testPrefix: prefix, testName: prefix + ":*"}, nil
			}
			if p.peek().typ != "name" {
				return nil, fmt.Errorf("expected name after :")
			}
			local = p.next().val
			fullName = prefix + ":" + local
		}
		return &xpStep{testKind: "name", testName: fullName, testLocal: local, testPrefix: prefix}, nil
	}
	return nil, fmt.Errorf("expected node test, got %q", p.peek().val)
}

// ---------- evaluation ----------

func xpValueToString(v xpValue, ctx *xpContext) string {
	switch v.kind {
	case xpNodes:
		if len(v.nodes) == 0 {
			return ""
		}
		return stringValue(v.nodes[0])
	case xpNumber:
		return xpNumberToString(v.num)
	case xpString:
		return v.str
	case xpBool:
		if v.b { return "true" }
		return "false"
	case xpRoundInt:
		return strconv.FormatInt(v.i, 10)
	}
	return ""
}
func xpValueToNumber(v xpValue, ctx *xpContext) float64 {
	switch v.kind {
	case xpNodes:
		if len(v.nodes) == 0 {
			return math.NaN()
		}
		return xpStringToNumber(stringValue(v.nodes[0]))
	case xpNumber:
		return v.num
	case xpString:
		return xpStringToNumber(v.str)
	case xpBool:
		if v.b { return 1 }
		return 0
	case xpRoundInt:
		return float64(v.i)
	}
	return math.NaN()
}
func xpValueToBool(v xpValue) bool {
	switch v.kind {
	case xpNodes:
		return len(v.nodes) > 0
	case xpNumber:
		return v.num != 0 && !math.IsNaN(v.num)
	case xpString:
		return len(v.str) > 0
	case xpBool:
		return v.b
	case xpRoundInt:
		return v.i != 0
	}
	return false
}
func xpStringToNumber(s string) float64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return math.NaN()
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return math.NaN()
	}
	return f
}
func xpNumberToString(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatFloat(f, 'f', -1, 64)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func (e *xpLitString) eval(ctx *xpContext) (xpValue, error) { return xpValue{kind: xpString, str: e.v}, nil }
func (e *xpLitNumber) eval(ctx *xpContext) (xpValue, error) { return xpValue{kind: xpNumber, num: e.v}, nil }
func (e *xpVar) eval(ctx *xpContext) (xpValue, error) { return xpValue{kind: xpString, str: ""}, nil }
func (e *xpUnary) eval(ctx *xpContext) (xpValue, error) {
	v, err := e.e.eval(ctx)
	if err != nil { return v, err }
	return xpValue{kind: xpNumber, num: -xpValueToNumber(v, ctx)}, nil
}

func (e *xpBinary) eval(ctx *xpContext) (xpValue, error) {
	// short circuit boolean? XPath evaluates both but keep simple
	if e.op == "or" {
		l, err := e.l.eval(ctx)
		if err != nil { return l, err }
		if xpValueToBool(l) {
			return xpValue{kind: xpBool, b: true}, nil
		}
		r, err := e.r.eval(ctx)
		if err != nil { return r, err }
		return xpValue{kind: xpBool, b: xpValueToBool(r)}, nil
	}
	if e.op == "and" {
		l, err := e.l.eval(ctx)
		if err != nil { return l, err }
		if !xpValueToBool(l) {
			return xpValue{kind: xpBool, b: false}, nil
		}
		r, err := e.r.eval(ctx)
		if err != nil { return r, err }
		return xpValue{kind: xpBool, b: xpValueToBool(r)}, nil
	}
	l, err := e.l.eval(ctx)
	if err != nil { return l, err }
	r, err := e.r.eval(ctx)
	if err != nil { return r, err }
	switch e.op {
	case "+", "-", "*", "div", "mod":
		ln := xpValueToNumber(l, ctx)
		rn := xpValueToNumber(r, ctx)
		switch e.op {
		case "+":
			return xpValue{kind: xpNumber, num: ln + rn}, nil
		case "-":
			return xpValue{kind: xpNumber, num: ln - rn}, nil
		case "*":
			return xpValue{kind: xpNumber, num: ln * rn}, nil
		case "div":
			return xpValue{kind: xpNumber, num: ln / rn}, nil
		case "mod":
			// integer mod like original library
			li := int64(ln)
			ri := int64(rn)
			if ri == 0 {
				return xpValue{}, fmt.Errorf("XPath error: runtime error: integer divide by zero")
			}
			return xpValue{kind: xpNumber, num: float64(li % ri)}, nil
		}
	case "=", "!=", "<", "<=", ">", ">=":
		return xpValue{kind: xpBool, b: xpCompare(e.op, l, r, ctx)}, nil
	}
	return xpValue{}, fmt.Errorf("unsupported operator %s", e.op)
}

func xpCompare(op string, l, r xpValue, ctx *xpContext) bool {
	// node-set involved
	if l.kind == xpNodes || r.kind == xpNodes {
		if op == "=" || op == "!=" {
			// boolean comparison if other is bool
			if l.kind != xpNodes && l.kind == xpBool {
				return applyCompareBool(op, xpValueToBool(l), xpValueToBool(r))
			}
			if r.kind != xpNodes && r.kind == xpBool {
				return applyCompareBool(op, xpValueToBool(l), xpValueToBool(r))
			}
			if l.kind == xpNodes && r.kind == xpNodes {
				for _, ln := range l.nodes {
					for _, rn := range r.nodes {
						ls, rs := stringValue(ln), stringValue(rn)
						if op == "=" && ls == rs { return true }
						if op == "!=" && ls != rs { return true }
					}
				}
				return false
			}
			// one nodes, other string/number
			var nodes []*domNode
			var other xpValue
			var swapped bool
			if l.kind == xpNodes { nodes = l.nodes; other = r } else { nodes = r.nodes; other = l; swapped = true }
			_ = swapped
			for _, n := range nodes {
				sv := stringValue(n)
				if other.kind == xpNumber {
					nv := xpStringToNumber(sv)
					if op == "=" && nv == other.num { return true }
					if op == "!=" && nv != other.num && !math.IsNaN(nv) { return true }
					if op == "!=" && math.IsNaN(nv) { /* NaN != x is ??? treat as false in xpath? skip */ }
				} else {
					ov := xpValueToString(other, ctx)
					if op == "=" && sv == ov { return true }
					if op == "!=" && sv != ov { return true }
				}
			}
			return false
		}
		// relational: numeric existential
		var lvals, rvals []float64
		if l.kind == xpNodes {
			for _, n := range l.nodes { lvals = append(lvals, xpStringToNumber(stringValue(n))) }
		} else {
			lvals = []float64{xpValueToNumber(l, ctx)}
		}
		if r.kind == xpNodes {
			for _, n := range r.nodes { rvals = append(rvals, xpStringToNumber(stringValue(n))) }
		} else {
			rvals = []float64{xpValueToNumber(r, ctx)}
		}
		for _, a := range lvals {
			for _, b := range rvals {
				if compareFloat(op, a, b) { return true }
			}
		}
		return false
	}
	// no nodes
	if op == "=" || op == "!=" {
		if l.kind == xpBool || r.kind == xpBool {
			return applyCompareBool(op, xpValueToBool(l), xpValueToBool(r))
		}
		if l.kind == xpNumber || l.kind == xpRoundInt || r.kind == xpNumber || r.kind == xpRoundInt {
			a, b := xpValueToNumber(l, ctx), xpValueToNumber(r, ctx)
			if math.IsNaN(a) || math.IsNaN(b) {
				return op == "!="
			}
			if op == "=" { return a == b }
			return a != b
		}
		ls, rs := xpValueToString(l, ctx), xpValueToString(r, ctx)
		if op == "=" { return ls == rs }
		return ls != rs
	}
	// relational numeric
	return compareFloat(op, xpValueToNumber(l, ctx), xpValueToNumber(r, ctx))
}
func applyCompareBool(op string, a, b bool) bool {
	if op == "=" { return a == b }
	return a != b
}
func compareFloat(op string, a, b float64) bool {
	if math.IsNaN(a) || math.IsNaN(b) { return false }
	switch op {
	case "<": return a < b
	case "<=": return a <= b
	case ">": return a > b
	case ">=": return a >= b
	}
	return false
}

func (e *xpUnion) eval(ctx *xpContext) (xpValue, error) {
	var out []*domNode
	for _, part := range e.parts {
		v, err := part.eval(ctx)
		if err != nil { return v, err }
		if v.kind != xpNodes {
			return xpValue{}, fmt.Errorf("expression must evaluate to a node-set")
		}
		out = append(out, v.nodes...)
	}
	return xpValue{kind: xpNodes, nodes: out}, nil
}

func (e *xpFilter) eval(ctx *xpContext) (xpValue, error) {
	v, err := e.base.eval(ctx)
	if err != nil { return v, err }
	nodes := v.nodes
	if v.kind == xpNodes && len(e.preds) > 0 {
		nodes, err = applyPredicates(nodes, e.preds, ctx)
		if err != nil { return v, err }
		v.nodes = nodes
	}
	if len(e.steps) > 0 {
		if v.kind != xpNodes {
			return xpValue{kind: xpNodes, nodes: nil}, nil
		}
		cur := v.nodes
		for _, st := range e.steps {
			cur, err = evalStep(cur, st, ctx)
			if err != nil { return v, err }
		}
		return xpValue{kind: xpNodes, nodes: cur}, nil
	}
	return v, nil
}

func applyPredicates(candidates []*domNode, preds []xpExpr, baseCtx *xpContext) ([]*domNode, error) {
	cur := candidates
	for _, pr := range preds {
		var next []*domNode
		size := len(cur)
		for idx, node := range cur {
			c := &xpContext{node: node, pos: idx + 1, size: size, doc: baseCtx.doc}
			v, err := pr.eval(c)
			if err != nil { return nil, err }
			keep := false
			switch v.kind {
			case xpNumber:
				if float64(idx+1) == v.num { keep = true }
			case xpRoundInt:
				if int64(idx+1) == v.i { keep = true }
			case xpNodes:
				keep = len(v.nodes) > 0
			case xpString:
				keep = len(v.str) > 0
			case xpBool:
				keep = v.b
			}
			if keep {
				next = append(next, node)
			}
		}
		cur = next
	}
	return cur, nil
}

func (e *xpPath) eval(ctx *xpContext) (xpValue, error) {
	var cur []*domNode
	if e.absolute {
		cur = []*domNode{ctx.doc}
	} else {
		cur = []*domNode{ctx.node}
	}
	var err error
	for _, st := range e.steps {
		cur, err = evalStep(cur, st, ctx)
		if err != nil {
			return xpValue{}, err
		}
	}
	return xpValue{kind: xpNodes, nodes: cur}, nil
}

func evalStep(contextNodes []*domNode, st *xpStep, baseCtx *xpContext) ([]*domNode, error) {
	var result []*domNode
	seen := map[*domNode]bool{}
	for _, ctxNode := range contextNodes {
		cands := axisNodes(ctxNode, st.axis, baseCtx.doc)
		// filter by test
		var filtered []*domNode
		for _, c := range cands {
			if nodeTestMatches(c, st, baseCtx.doc) {
				filtered = append(filtered, c)
			}
		}
		if len(st.preds) > 0 {
			var err error
			filtered, err = applyPredicatesWithAxisOrder(filtered, st, baseCtx)
			if err != nil {
				return nil, err
			}
		}
		for _, c := range filtered {
			if !seen[c] {
				seen[c] = true
				result = append(result, c)
			}
		}
	}
	// sort by document order
	sort.SliceStable(result, func(i, j int) bool { return result[i].Order < result[j].Order })
	return result, nil
}

func applyPredicatesWithAxisOrder(candidates []*domNode, st *xpStep, baseCtx *xpContext) ([]*domNode, error) {
	// candidates already in axis order (as returned). applyPredicates uses that order.
	return applyPredicates(candidates, st.preds, baseCtx)
}

func isReverseAxis(axis string) bool {
	return axis == "ancestor" || axis == "ancestor-or-self" || axis == "preceding" || axis == "preceding-sibling"
}

func axisNodes(ctxNode *domNode, axis string, doc *domNode) []*domNode {
	switch axis {
	case "child":
		if ctxNode.Type == nodeAttr {
			return nil
		}
		out := make([]*domNode, len(ctxNode.Children))
		copy(out, ctxNode.Children)
		return out
	case "parent":
		if ctxNode.Parent != nil {
			return []*domNode{ctxNode.Parent}
		}
		return nil
	case "self":
		return []*domNode{ctxNode}
	case "descendant":
		var out []*domNode
		collectDescendants(ctxNode, &out)
		return out
	case "descendant-or-self":
		out := []*domNode{ctxNode}
		collectDescendants(ctxNode, &out)
		return out
	case "ancestor":
		var out []*domNode
		for p := ctxNode.Parent; p != nil; p = p.Parent {
			out = append(out, p)
		}
		return out
	case "ancestor-or-self":
		out := []*domNode{ctxNode}
		for p := ctxNode.Parent; p != nil; p = p.Parent {
			out = append(out, p)
		}
		return out
	case "following-sibling":
		if ctxNode.Parent == nil || ctxNode.Type == nodeAttr {
			return nil
		}
		sibs := ctxNode.Parent.Children
		idx := indexOfNode(sibs, ctxNode)
		if idx < 0 { return nil }
		out := make([]*domNode, len(sibs)-idx-1)
		copy(out, sibs[idx+1:])
		return out
	case "preceding-sibling":
		if ctxNode.Parent == nil || ctxNode.Type == nodeAttr {
			return nil
		}
		sibs := ctxNode.Parent.Children
		idx := indexOfNode(sibs, ctxNode)
		if idx < 0 { return nil }
		out := make([]*domNode, idx)
		for i := 0; i < idx; i++ {
			out[i] = sibs[idx-1-i]
		}
		return out
	case "attribute":
		if ctxNode.Type != nodeElement {
			return nil
		}
		out := make([]*domNode, len(ctxNode.Attrs))
		copy(out, ctxNode.Attrs)
		return out
	case "following":
		// nodes after ctxNode's subtree, excluding descendants and ancestors' ??? simplified: all non-attr nodes with Order > subtreeEnd
		end := subtreeEndOrder(ctxNode)
		var out []*domNode
		collectAllNodes(doc, &out)
		var res []*domNode
		for _, n := range out {
			if n.Order > end && n.Type != nodeAttr {
				// exclude doc? doc order is 0
				res = append(res, n)
			}
		}
		return res
	case "preceding":
		// nodes before ctxNode excluding ancestors
		anc := map[*domNode]bool{}
		for p := ctxNode.Parent; p != nil; p = p.Parent { anc[p] = true }
		var out []*domNode
		collectAllNodes(doc, &out)
		var res []*domNode
		// reverse document order
		for i := len(out) - 1; i >= 0; i-- {
			n := out[i]
			if n.Order < ctxNode.Order && !anc[n] && n.Type != nodeAttr && n != ctxNode {
				res = append(res, n)
			}
		}
		return res
	}
	return nil
}

func indexOfNode(list []*domNode, n *domNode) int {
	for i, x := range list { if x == n { return i } }
	return -1
}
func collectDescendants(n *domNode, out *[]*domNode) {
	for _, c := range n.Children {
		*out = append(*out, c)
		collectDescendants(c, out)
	}
}
func collectAllNodes(n *domNode, out *[]*domNode) {
	*out = append(*out, n)
	for _, c := range n.Children {
		collectAllNodes(c, out)
	}
}
func subtreeEndOrder(n *domNode) int {
	max := n.Order
	for _, c := range n.Children {
		e := subtreeEndOrder(c)
		if e > max { max = e }
	}
	// attributes are between element and children in order but are not descendants for following axis:
	// if node is element, its end should be after children; attrs already < children, fine.
	return max
}

// namespace prefix map for document
func docPrefixMap(doc *domNode) map[string]string {
	m := map[string]string{}
	var walk func(n *domNode)
	walk = func(n *domNode) {
		if n.Type == nodeElement {
			for _, a := range n.Attrs {
				if a.Prefix == "xmlns" {
					// a.Local is prefix, Data is URI
					if _, ok := m[a.Local]; !ok {
						m[a.Local] = a.Data
					}
				}
			}
		}
		for _, c := range n.Children { walk(c) }
	}
	walk(doc)
	return m
}

func nodeTestMatches(n *domNode, st *xpStep, doc *domNode) bool {
	switch st.testKind {
	case "node":
		// node() matches everything except attributes when axis is attribute? child/desc etc nodes are not attrs (attrs only via attribute axis list)
		// For attribute axis, node() should match attributes (XPath spec: node() on attribute axis matches attr nodes)
		// Our axisNodes for attribute returns attr nodes; accept them.
		return true
	case "text":
		return n.Type == nodeText
	case "comment":
		return n.Type == nodeComment
	case "pi":
		// original library had a bug returning elements for //processing-instruction(), but we implement correctly
		if n.Type != nodePI {
			// mimic bug only for axis descendant searches? Keep correct:
			return false
		}
		if st.hasPIArg {
			return n.PITarget == st.piArg
		}
		return true
	case "*":
		if n.Type == nodeAttr {
			if st.testPrefix != "" {
				return prefixMatches(n, st.testPrefix, doc)
			}
			return true
		}
		if n.Type != nodeElement {
			return false
		}
		if st.testPrefix != "" {
			return prefixMatches(n, st.testPrefix, doc)
		}
		return true
	case "name":
		if st.axis == "attribute" {
			if n.Type != nodeAttr { return false }
			return nameMatches(n, st, doc)
		}
		if n.Type != nodeElement {
			return false
		}
		return nameMatches(n, st, doc)
	}
	return false
}

func prefixMatches(n *domNode, prefix string, doc *domNode) bool {
	pm := docPrefixMap(doc)
	if uri, ok := pm[prefix]; ok {
		return n.NSURI == uri
	}
	return n.Prefix == prefix
}
func nameMatches(n *domNode, st *xpStep, doc *domNode) bool {
	if n.Local != st.testLocal {
		return false
	}
	if st.testPrefix == "" {
		return n.Prefix == ""
	}
	pm := docPrefixMap(doc)
	if uri, ok := pm[st.testPrefix]; ok {
		return n.NSURI == uri
	}
	return n.Prefix == st.testPrefix
}

// ---------- functions ----------

func (e *xpFuncCall) eval(ctx *xpContext) (xpValue, error) {
	name := e.name
	// context-dependent zero-arg functions
	switch name {
	case "last":
		return xpValue{kind: xpNumber, num: float64(ctx.size)}, nil
	case "position":
		return xpValue{kind: xpNumber, num: float64(ctx.pos)}, nil
	case "true":
		return xpValue{kind: xpBool, b: true}, nil
	case "false":
		return xpValue{kind: xpBool, b: false}, nil
	}
	// evaluate args lazily for some? evaluate all for most
	var args []xpValue
	for _, a := range e.args {
		v, err := a.eval(ctx)
		if err != nil { return v, err }
		args = append(args, v)
	}
	argNodes := func(i int) []*domNode {
		if i >= len(args) || args[i].kind != xpNodes { return nil }
		return args[i].nodes
	}
	argString := func(i int) string {
		if i >= len(args) {
			// context node string
			return stringValue(ctx.node)
		}
		return xpValueToString(args[i], ctx)
	}
	argNumber := func(i int) float64 {
		if i >= len(args) { return xpStringToNumber(stringValue(ctx.node)) }
		return xpValueToNumber(args[i], ctx)
	}
	switch name {
	case "count":
		if len(args) == 0 { return xpValue{}, fmt.Errorf("count error") }
		if args[0].kind != xpNodes { return xpValue{kind: xpNumber, num: 0}, nil }
		return xpValue{kind: xpNumber, num: float64(len(args[0].nodes))}, nil
	case "sum":
		nodes := argNodes(0)
		sum := 0.0
		for _, n := range nodes {
			sum += xpStringToNumber(stringValue(n))
		}
		return xpValue{kind: xpNumber, num: sum}, nil
	case "string":
		if len(args) == 0 {
			return xpValue{kind: xpString, str: stringValue(ctx.node)}, nil
		}
		return xpValue{kind: xpString, str: xpValueToString(args[0], ctx)}, nil
	case "number":
		if len(args) == 0 {
			return xpValue{kind: xpNumber, num: xpStringToNumber(stringValue(ctx.node))}, nil
		}
		return xpValue{kind: xpNumber, num: xpValueToNumber(args[0], ctx)}, nil
	case "boolean":
		return xpValue{kind: xpBool, b: xpValueToBool(args[0])}, nil
	case "not":
		return xpValue{kind: xpBool, b: !xpValueToBool(args[0])}, nil
	case "name":
		nodes := argNodes(0)
		if len(args) == 0 {
			// context
			if ctx.node.Type == nodeElement || ctx.node.Type == nodeAttr { return xpValue{kind: xpString, str: ctx.node.QName}, nil }
			return xpValue{kind: xpString, str: ""}, nil
		}
		if len(nodes) == 0 { return xpValue{kind: xpString, str: ""}, nil }
		n := nodes[0]
		if n.Type == nodeElement || n.Type == nodeAttr { return xpValue{kind: xpString, str: n.QName}, nil }
		return xpValue{kind: xpString, str: ""}, nil
	case "local-name":
		var n *domNode
		if len(args) == 0 { n = ctx.node } else {
			nodes := argNodes(0)
			if len(nodes) == 0 { return xpValue{kind: xpString, str: ""}, nil }
			n = nodes[0]
		}
		if n.Type == nodeElement || n.Type == nodeAttr { return xpValue{kind: xpString, str: n.Local}, nil }
		return xpValue{kind: xpString, str: ""}, nil
	case "namespace-uri":
		var n *domNode
		if len(args) == 0 { n = ctx.node } else {
			nodes := argNodes(0)
			if len(nodes) == 0 { return xpValue{kind: xpString, str: ""}, nil }
			n = nodes[0]
		}
		if n.Type == nodeElement || n.Type == nodeAttr { return xpValue{kind: xpString, str: n.NSURI}, nil }
		return xpValue{kind: xpString, str: ""}, nil
	case "concat":
		var b strings.Builder
		for _, a := range args { b.WriteString(xpValueToString(a, ctx)) }
		return xpValue{kind: xpString, str: b.String()}, nil
	case "starts-with":
		return xpValue{kind: xpBool, b: strings.HasPrefix(argString(0), argString(1))}, nil
	case "contains":
		return xpValue{kind: xpBool, b: strings.Contains(argString(0), argString(1))}, nil
	case "substring-before":
		s, sep := argString(0), argString(1)
		if sep == "" { return xpValue{kind: xpString, str: ""}, nil }
		idx := strings.Index(s, sep)
		if idx < 0 { return xpValue{kind: xpString, str: ""}, nil }
		return xpValue{kind: xpString, str: s[:idx]}, nil
	case "substring-after":
		s, sep := argString(0), argString(1)
		if sep == "" { return xpValue{kind: xpString, str: s}, nil }
		idx := strings.Index(s, sep)
		if idx < 0 { return xpValue{kind: xpString, str: ""}, nil }
		return xpValue{kind: xpString, str: s[idx+len(sep):]}, nil
	case "substring":
		s := argString(0)
		runes := []rune(s)
		start := xpRoundXPath(argNumber(1))
		if len(args) > 2 {
			length := xpRoundXPath(argNumber(2))
			// XPath substring: characters positions >= start and < start+length
			var out []rune
			for i, r := range runes {
				pos := float64(i + 1)
				if pos >= start && pos < start+length { out = append(out, r) }
			}
			return xpValue{kind: xpString, str: string(out)}, nil
		}
		var out []rune
		for i, r := range runes {
			if float64(i+1) >= start { out = append(out, r) }
		}
		return xpValue{kind: xpString, str: string(out)}, nil
	case "string-length":
		s := argString(0)
		return xpValue{kind: xpNumber, num: float64(utf8.RuneCountInString(s))}, nil
	case "normalize-space":
		s := argString(0)
		return xpValue{kind: xpString, str: strings.Join(strings.Fields(s), " ")}, nil
	case "translate":
		s, from, to := argString(0), argString(1), argString(2)
		fromR := []rune(from)
		toR := []rune(to)
		m := map[rune]rune{}
		del := map[rune]bool{}
		for i, fr := range fromR {
			if _, exists := m[fr]; exists || del[fr] { continue }
			if i < len(toR) { m[fr] = toR[i] } else { del[fr] = true }
		}
		var b strings.Builder
		for _, r := range s {
			if del[r] { continue }
			if rep, ok := m[r]; ok { b.WriteRune(rep) } else { b.WriteRune(r) }
		}
		return xpValue{kind: xpString, str: b.String()}, nil
	case "floor":
		return xpValue{kind: xpNumber, num: math.Floor(argNumber(0))}, nil
	case "ceiling":
		return xpValue{kind: xpNumber, num: math.Ceil(argNumber(0))}, nil
	case "round":
		return xpValue{kind: xpRoundInt, i: int64(math.Round(argNumber(0)))}, nil
	case "id":
		ids := strings.Fields(argString(0))
		var out []*domNode
		idSet := map[string]bool{}
		for _, id := range ids { idSet[id] = true }
		// walk doc
		var all []*domNode
		collectAllNodes(ctx.doc, &all)
		for _, n := range all {
			if n.Type == nodeElement {
				for _, a := range n.Attrs {
					if a.Local == "id" && idSet[a.Data] {
						out = append(out, n)
						break
					}
				}
			}
		}
		return xpValue{kind: xpNodes, nodes: out}, nil
	}
	return xpValue{}, fmt.Errorf("not yet support this function %s()", name)
}
func xpRoundXPath(f float64) float64 {
	// XPath round: floor(x+0.5)
	return math.Floor(f + 0.5)
}

// ---------- processing ----------

func processXPathQuery(content []byte, out io.Writer, single bool) error {
	// parse document (non-strict)
	doc, err := parseXMLDocument(content, false)
	if err != nil {
		if err == errInvalidXMLDocument {
			return err
		}
		return err
	}
	queryStr := currentOptions.xpath
	if single {
		queryStr = currentOptions.extract
	}
	expr, parseErr := xpParse(queryStr)
	if parseErr != nil {
		if single {
			if uf, ok := parseErr.(*xpUnknownFuncErr); ok {
				return fmt.Errorf("XPath error: %s", uf.Error())
			}
			// arity errors recorded become specific?
			// Our parser returns arity as generic error string for count/substring
			msg := parseErr.Error()
			if strings.HasPrefix(msg, "xpath:") {
				return fmt.Errorf("XPath error: %s", msg)
			}
			return fmt.Errorf("XPath error: expression must evaluate to a node-set")
		}
		return fmt.Errorf("unable to parse the XPath query")
	}
	ctx := &xpContext{node: doc, pos: 1, size: 1, doc: doc}
	result, evalErr := expr.eval(ctx)
	if evalErr != nil {
		if single {
			// xmlquery path: if error already starts with XPath error, keep; else wrap
			if strings.HasPrefix(evalErr.Error(), "XPath error:") {
				return evalErr
			}
			return fmt.Errorf("XPath error: %s", evalErr.Error())
		}
		// for -x, runtime errors are reported as XPath error: ...
		if strings.HasPrefix(evalErr.Error(), "XPath error:") {
			return evalErr
		}
		return fmt.Errorf("XPath error: %s", evalErr.Error())
	}
	if single {
		if result.kind != xpNodes {
			return nil
		}
		if len(result.nodes) == 0 {
			return nil
		}
		nodes := result.nodes[:1]
		writeXPathResults(nodes, out)
		return nil
	}
	// xpath (-x)
	switch result.kind {
	case xpNodes:
		writeXPathResults(result.nodes, out)
		return nil
	case xpNumber:
		fmt.Fprintf(out, "%.0f\n", result.num)
		return nil
	case xpString:
		fmt.Fprintf(out, "%s\n", result.str)
		return nil
	default:
		// bool / round-int etc.
		if result.kind == xpBool {
			return fmt.Errorf("unknown type error: %v", result.b)
		}
		if result.kind == xpRoundInt {
			return fmt.Errorf("unknown type error: %v", result.i)
		}
		return fmt.Errorf("unknown type error: %v", result.str)
	}
}

func writeXPathResults(nodes []*domNode, out io.Writer) {
	for _, n := range nodes {
		if currentOptions.node {
			s := serializeXMLNode(n)
			formatted, err := formatXMLString(s)
			if err != nil {
				fmt.Fprint(out, formatted)
				continue
			}
			fmt.Fprint(out, formatted)
			fmt.Fprint(out, "\n")
		} else {
			text := strings.TrimSpace(innerText(n))
			fmt.Fprint(out, text)
			fmt.Fprint(out, "\n")
		}
	}
}
