// ---------- CSS selector parsing (cascadia-like) ----------

type cssSelectorGroup []*cssComplex

type cssComplex struct {
	parts []*cssCompoundPart
}
type cssCompoundPart struct {
	combinator byte // ' ', '>', '+', '~'  for this and following? We'll store combinator BEFORE this compound (first is ' ')
	compound   *cssCompound
}
type cssCompound struct {
