	n:=len(s)
	i++
	for i<n && isCSSSpace(s[i]) { i++ }
	name, ni, err:=cssParseIdent(s,i)
	if err!=nil { return cssCond{},0,err }
	i=ni
	for i<n && isCSSSpace(s[i]) { i++ }
	if i<n && s[i]==']' {
		return cssCond{kind:"attr", attrName: strings.ToLower(name)}, i+1, nil
	}
	// operator
	op:=""
	if i+1<n && (s[i]=='~'||s[i]=='|'||s[i]=='^'||s[i]=='$'||s[i]=='*'||s[i]=='!') && s[i+1]=='=' {
		op=string([]byte{s[i],'='}); i+=2
