func cssParseHasArg(arg string) ([]*cssRelative, error) {
	parts, err:=splitTopLevelCommas(arg)
	if err!=nil { return nil, err }
	var out []*cssRelative
	for _, part:=range parts {
		part=strings.TrimSpace(part)
		if part=="" { return nil, fmt.Errorf("empty has") }
		comb:=byte(0) // descendant
		if part[0]=='>'||part[0]=='+'||part[0]=='~' {
