package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// process -j flag
func processJSONFlag(content []byte, out io.Writer) error {
	opts := currentOptions
	indentUnit := "  "
	if opts.compact {
		indentUnit = ""
	}
	if !opts.html {
		kind := detectContent(content)
		if kind == kindJSON {
			// decode one JSON value generically (numbers -> float64, maps sorted on marshal)
			dec := json.NewDecoder(bytes.NewReader(content))
			var data interface{}
			if err := dec.Decode(&data); err != nil {
				return fmt.Errorf("error while parsing JSON: %s", err.Error())
			}
			raw, err := json.Marshal(data)
			if err != nil {
				return fmt.Errorf("error while parsing JSON: %s", err.Error())
			}
			s, err := formatJSONString(string(raw), indentUnit)
			if err != nil {
				return fmt.Errorf("error while parsing JSON: %s", err.Error())
			}
			fmt.Fprint(out, s)
			fmt.Fprint(out, "\n")
			return nil
		}
		if kind == kindUnknown {
			data := map[string]interface{}{"text": ""}
			raw, _ := json.Marshal(data)
			s, err := formatJSONString(string(raw), indentUnit)
			if err != nil {
				return fmt.Errorf("error while parsing JSON: %s", err.Error())
			}
			fmt.Fprint(out, s)
			fmt.Fprint(out, "\n")
			return nil
		}
	}
	// XML / HTML -> JSON conversion
	doc, err := parseXMLDocument(content, true)
	if err != nil {
		if err == errInvalidXMLDocument {
			return fmt.Errorf("error while parsing XML: xmlquery: invalid XML document")
		}
		return fmt.Errorf("error while parsing XML: %s", err.Error())
	}
	data := convertDocumentToJSON(doc, opts.depth)
	raw, err := json.Marshal(data)
	if err != nil {
		return fmt.Errorf("error while parsing JSON: %s", err.Error())
	}
	s, err := formatJSONString(string(raw), indentUnit)
	if err != nil {
		return fmt.Errorf("error while parsing JSON: %s", err.Error())
	}
	_ = io.Discard
	fmt.Fprint(out, s)
	fmt.Fprint(out, "\n")
	return nil
}

func convertDocumentToJSON(doc *domNode, maxDepth int) map[string]interface{} {
	result := map[string]interface{}{}
	// document-level text pieces
	var textPieces []string
	// group element children
	grouped := map[string][]interface{}{}
	var order []string // not needed - marshal sorts
	for _, child := range doc.Children {
		if child.Type == nodeText {
			t := strings.TrimSpace(child.Data)
			if t != "" {
				textPieces = append(textPieces, t)
			}
		} else if child.Type == nodeElement {
			v := convertElementToJSON(child, 0, maxDepth)
			if _, ok := grouped[child.Local]; !ok {
				order = append(order, child.Local)
			}
			grouped[child.Local] = append(grouped[child.Local], v)
		}
	}
	if len(textPieces) > 0 {
		result["#text"] = strings.Join(textPieces, "\n")
	}
	for name, list := range grouped {
		if len(list) == 1 {
			result[name] = list[0]
		} else {
			result[name] = list
		}
	}
	_ = order
	return result
}

func convertElementToJSON(el *domNode, depth int, maxDepth int) interface{} {
	if maxDepth >= 0 && depth >= maxDepth {
		return nodeTextContent(el)
	}
	// collect direct text pieces, element children
	var textPieces []string
	var childElements []*domNode
	for _, c := range el.Children {
		if c.Type == nodeText {
			t := strings.TrimSpace(c.Data)
			if t != "" {
				textPieces = append(textPieces, t)
			}
		} else if c.Type == nodeElement {
			childElements = append(childElements, c)
		}
	}
	hasAttrs := len(el.Attrs) > 0
	if !hasAttrs && len(childElements) == 0 {
		if len(textPieces) == 0 {
			return map[string]interface{}{}
		}
		return strings.Join(textPieces, "\n")
	}
	obj := map[string]interface{}{}
	if len(textPieces) > 0 {
		obj["#text"] = strings.Join(textPieces, "\n")
	}
	for _, a := range el.Attrs {
		key := "@" + a.Local
		obj[key] = a.Data
	}
	// children grouped
	grouped := map[string][]interface{}{}
	for _, ch := range childElements {
		v := convertElementToJSON(ch, depth+1, maxDepth)
		grouped[ch.Local] = append(grouped[ch.Local], v)
	}
	for name, list := range grouped {
		if len(list) == 1 {
			obj[name] = list[0]
		} else {
			obj[name] = list
		}
	}
	return obj
}

func nodeTextContent(n *domNode) string {
	// join text content of node and descendants ordered by children sequence, using join over child results
	if n.Type == nodeText {
		return strings.TrimSpace(n.Data)
	}
	if n.Type != nodeElement && n.Type != nodeDocument {
		return ""
	}
	var parts []string
	for _, c := range n.Children {
		if c.Type == nodeText || c.Type == nodeElement {
			parts = append(parts, nodeTextContent(c))
		}
	}
	return strings.Join(parts, "\n")
}
