import pathlib
p=pathlib.Path("dom.go"); s=p.read_text()
# heading implicit close fix: only if current top is heading.
s=s.replace("""	case "h1", "h2", "h3", "h4", "h5", "h6":
		closeTag("h1", "h2", "h3", "h4", "h5", "h6")""","""	case "h1", "h2", "h3", "h4", "h5", "h6":
		// only pop the current node if it is itself a heading
		if len(s) > 0 {
			t := s[len(s)-1].Local
			if t == "h1" || t == "h2" || t == "h3" || t == "h4" || t == "h5" || t == "h6" {
				s = s[:len(s)-1]
				*stack = s
			}
		}""")

# Insert table/select/form handling before "// implicit closes" in body content creation
old="""			// implicit closes
			applyImplicitClose(&stack, name)"""
new="""			// --- HTML tree-construction special cases ---
			// inside <select>: only a few tags are allowed
			if inSelect(stack) {
				if name == "select" {
					// treated as </select>
					for i := len(stack) - 1; i >= 0; i-- {
						if stack[i].Local == "select" { stack = stack[:i]; break }
					}
					continue
				}
				if name == "input" || name == "textarea" || name == "keygen" {
					// pop select and reprocess
					for i := len(stack) - 1; i >= 0; i-- {
						if stack[i].Local == "select" { stack = stack[:i]; break }
					}
				} else if name != "option" && name != "optgroup" && name != "script" && name != "template" {
					continue
				}
			}
			if name == "form" {
				// nested form start is ignored
				hasForm := false
				for _, sn := range stack { if sn.Local == "form" { hasForm = true; break } }
				if hasForm { continue }
			}
			// table-internal tags
			if name == "tr" || name == "td" || name == "th" || name == "tbody" || name == "thead" || name == "tfoot" || name == "caption" || name == "colgroup" || name == "col" {
				if !hasAncestorTag(stack, "table") {
					continue // ignore token, content flows into current context
				}
				if name == "tr" {
					applyImplicitClose(&stack, "tr")
					if cur := current(); cur != nil && cur.Local == "table" {
						// implicit tbody
						tb := &domNode{Type: nodeElement, QName: "tbody", Local: "tbody", Parent: cur, Order: order}; order++
						cur.Children = append(cur.Children, tb); push(tb)
					}
				} else if name == "td" || name == "th" {
					applyImplicitClose(&stack, name)
					if cur := current(); cur != nil && cur.Local == "table" {
						tb := &domNode{Type: nodeElement, QName: "tbody", Local: "tbody", Parent: cur, Order: order}; order++
						cur.Children = append(cur.Children, tb); push(tb)
						tr := &domNode{Type: nodeElement, QName: "tr", Local: "tr", Parent: tb, Order: order}; order++
						tb.Children = append(tb.Children, tr); push(tr)
					} else if cur := current(); cur != nil && (cur.Local == "tbody" || cur.Local == "thead" || cur.Local == "tfoot") {
						tr := &domNode{Type: nodeElement, QName: "tr", Local: "tr", Parent: cur, Order: order}; order++
						cur.Children = append(cur.Children, tr); push(tr)
					}
				} else {
					// sections/caption/colgroup: pop back to table
					for len(stack) > 0 {
						top := stack[len(stack)-1]
						if top.Local == "table" { break }
						stack = stack[:len(stack)-1]
					}
				}
			}
			// implicit closes
			applyImplicitClose(&stack, name)"""
if old not in s:
    print("old not found")
else:
    s=s.replace(old,new)
# helper functions at end
s += """

func inSelect(stack []*domNode) bool {
	for i := len(stack) - 1; i >= 0; i-- {
		if stack[i].Local == "select" { return true }
		if stack[i].Local == "template" { return false }
	}
	return false
}
func hasAncestorTag(stack []*domNode, tag string) bool {
	for _, n := range stack { if n.Local == tag { return true } }
	return false
}
"""
