}
func decodeUTF16Custom(data []byte, bigEndian bool) []byte {
	var buf bytes.Buffer
	for i := 0; i+1 < len(data); i += 2 {
		var u uint16
		if bigEndian {
			u = uint16(data[i])<<8 | uint16(data[i+1])
		} else {
			u = uint16(data[i+1])<<8 | uint16(data[i])
		}
		if u >= 0xD800 && u < 0xDC00 && i+3 < len(data) {
			var u2 uint16
