				u2 = uint16(data[i+2])<<8 | uint16(data[i+3])
			} else {
				u2 = uint16(data[i+3])<<8 | uint16(data[i+2])
			}
			if u2 >= 0xDC00 && u2 < 0xE000 {
				buf.WriteRune(utf16.DecodeRune(rune(u), rune(u2)))
				i += 2
				continue
			}
		}
		if u == 0 {
			buf.WriteRune('\uFFFD')
		} else {
			buf.WriteRune(rune(u))
		}
	}
	_ = utf8.RuneLen
	return buf.Bytes()
}

func charsetReader(label string, input io.Reader, strictConvert bool) (io.Reader, error) {
	data, err := io.ReadAll(input)
	if err != nil {
		return nil, err
	}
	norm := strings.ToLower(strings.TrimSpace(label))
	// common label normalization: remove underscores for matching some aliases
	switch norm {
	case "utf-8", "utf8", "unicode-1-1-utf-8":
		return bytes.NewReader(data), nil
	case "utf-16":
		// observed original: ASCII content passes through essentially as UTF-8 bytes
		return bytes.NewReader(data), nil
	case "utf-16le", "utf-16-le":
		return bytes.NewReader(decodeUTF16Custom(data, false)), nil
	case "utf-16be", "utf-16-be":
		return bytes.NewReader(decodeUTF16Custom(data, true)), nil
	case "iso-8859-1", "iso8859-1", "iso88591", "iso_8859-1", "latin1", "l1", "iso-ir-100", "csisolatin1":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune { return rune(b) })), nil
	case "iso-8859-15", "iso8859-15", "latin9", "l9":
