		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if r, ok := special[b]; ok {
				return r
			}
			return rune(b)
		})), nil
	case "iso-8859-2", "iso-8859-3", "iso-8859-4", "iso-8859-5", "iso-8859-6", "iso-8859-7", "iso-8859-8", "iso-8859-9", "iso-8859-10", "iso-8859-13", "iso-8859-14", "iso-8859-16":
		// Approximation: latin1 for bytes (correct for many, not all mappings)
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune { return rune(b) })), nil
	case "windows-1252", "cp1252", "ms-ee", "x-cp1252":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b >= 0x80 && b < 0xA0 {
				if r, ok := cp1252High[b]; ok {
					return r
				}
				return '\uFFFD'
			}
			return rune(b)
		})), nil
	case "windows-1250", "windows-1251", "windows-1253", "windows-1254", "windows-1255", "windows-1256", "windows-1257", "windows-1258", "cp1250", "cp1251":
		// approximation: use cp1252 for high range, latin1 else (Cyrillic windows-1251 differs; bytes >=A0 map approximated by latin1 in many cases but Cyrillic letters would be wrong; accept)
		if norm == "windows-1251" || norm == "cp1251" {
			return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
				if b < 0x80 { return rune(b) }
				if b >= 0xC0 { return '\u0410' + rune(b-0xC0) }
				if r, ok := cp1252High[b]; ok { return r }
				// 0xA0-0xBF approximations omitted -> use latin1 for some punctuation, replacement for letters would be needed
				if b == 0xA8 { return '\u0401' }
				if b == 0xB8 { return '\u0451' }
				return rune(b)
			})), nil
		}
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b >= 0x80 && b < 0xA0 {
				if r, ok := cp1252High[b]; ok { return r }
				return '\uFFFD'
			}
			return rune(b)
		})), nil
	case "us-ascii", "ascii", "ansi_x3.4-1968", "iso-ir-6":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b < 0x80 { return rune(b) }
			return '\uFFFD'
		})), nil
