		if strings.HasPrefix(norm, pfx) {
			return bytes.NewReader(data), nil
		}
	}
	if norm == "shift_jis" || norm == "sjis" || norm == "big5" || norm == "euc-jp" || norm == "euc-kr" {
		return bytes.NewReader(data), nil
	}
	if strictConvert {
		return nil, fmt.Errorf("unsupported charset: %q", label)
	}
	return nil, fmt.Errorf("ianaindex: invalid encoding name")
}
