			if u2 >= 0xDC00 && u2 < 0xE000 {
				buf.WriteRune(utf16.DecodeRune(rune(u), rune(u2)))
				i += 2
				continue
			}
		}
		if u == 0 {
			buf.WriteRune('\uFFFD')
		} else {
			buf.WriteRune(rune(u))
		}
	}
	_ = utf8.RuneLen
	return buf.Bytes()
}

func charsetReader(label string, input io.Reader, strictConvert bool) (io.Reader, error) {
	data, err := io.ReadAll(input)
	if err != nil {
		return nil, err
	}
	norm := strings.ToLower(strings.TrimSpace(label))
	// common label normalization: remove underscores for matching some aliases
	switch norm {
	case "utf-8", "utf8", "unicode-1-1-utf-8":
		return bytes.NewReader(data), nil
	case "utf-16":
		// observed original: ASCII content passes through essentially as UTF-8 bytes
		return bytes.NewReader(data), nil
	case "utf-16le", "utf-16-le":
		return bytes.NewReader(decodeUTF16Custom(data, false)), nil
	case "utf-16be", "utf-16-be":
		return bytes.NewReader(decodeUTF16Custom(data, true)), nil
	case "iso-8859-1", "iso8859-1", "iso88591", "iso_8859-1", "latin1", "l1", "iso-ir-100", "csisolatin1":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune { return rune(b) })), nil
	case "iso-8859-15", "iso8859-15", "latin9", "l9":
		special := map[byte]rune{0xA4: '\u20ac', 0xA6: '\u0160', 0xA8: '\u0161', 0xB4: '\u017d', 0xB8: '\u017e', 0xBC: '\u0152', 0xBD: '\u0153', 0xBE: '\u0178'}
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if r, ok := special[b]; ok {
				return r
			}
			return rune(b)
		})), nil
	case "iso-8859-2", "iso-8859-3", "iso-8859-4", "iso-8859-5", "iso-8859-6", "iso-8859-7", "iso-8859-8", "iso-8859-9", "iso-8859-10", "iso-8859-13", "iso-8859-14", "iso-8859-16":
		// Approximation: latin1 for bytes (correct for many, not all mappings)
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune { return rune(b) })), nil
	case "windows-1252", "cp1252", "ms-ee", "x-cp1252":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b >= 0x80 && b < 0xA0 {
				if r, ok := cp1252High[b]; ok {
					return r
				}
				return '\uFFFD'
			}
			return rune(b)
		})), nil
	case "windows-1250", "windows-1251", "windows-1253", "windows-1254", "windows-1255", "windows-1256", "windows-1257", "windows-1258", "cp1250", "cp1251":
		// approximation: use cp1252 for high range, latin1 else (Cyrillic windows-1251 differs; bytes >=A0 map approximated by latin1 in many cases but Cyrillic letters would be wrong; accept)
		if norm == "windows-1251" || norm == "cp1251" {
			return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
				if b < 0x80 { return rune(b) }
				if b >= 0xC0 { return '\u0410' + rune(b-0xC0) }
				if r, ok := cp1252High[b]; ok { return r }
				// 0xA0-0xBF approximations omitted -> use latin1 for some punctuation, replacement for letters would be needed
				if b == 0xA8 { return '\u0401' }
				if b == 0xB8 { return '\u0451' }
				return rune(b)
			})), nil
		}
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b >= 0x80 && b < 0xA0 {
				if r, ok := cp1252High[b]; ok { return r }
				return '\uFFFD'
			}
			return rune(b)
		})), nil
	case "us-ascii", "ascii", "ansi_x3.4-1968", "iso-ir-6":
		return bytes.NewReader(decodeSingleByte(data, func(b byte) rune {
			if b < 0x80 { return rune(b) }
			return '\uFFFD'
		})), nil
	case "koi8-r", "koi8-u", "koi8":
		// Passthrough: Go utf8 decoding will replace invalid bytes similar-ish for content; tags (ASCII) parse.
		return bytes.NewReader(data), nil
	}
	// recognized IANA labels we don't fully implement: let ASCII markup pass through
	knownPrefixes := []string{"shift", "gb", "big5", "euc", "iso-2022", "windows-", "x-", "cp", "ibm", "euc-jp", "euc-kr", "gbk", "gb18030", "hz", "johab", "ks"}
	for _, pfx := range knownPrefixes {
		if strings.HasPrefix(norm, pfx) {
			return bytes.NewReader(data), nil
		}
	}
	if norm == "shift_jis" || norm == "sjis" || norm == "big5" || norm == "euc-jp" || norm == "euc-kr" {
		return bytes.NewReader(data), nil
	}
	if strictConvert {
		return nil, fmt.Errorf("unsupported charset: %q", label)
	}
	return nil, fmt.Errorf("ianaindex: invalid encoding name")
}
